// Spells, cantrips and focus spells.

export const SPELLS = [
  // Cantrips
  { name: 'Caustic Blast', level: 1, cantrip: true, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You fling a large glob of acid that immediately detonates, spraying nearby creatures. Creatures in the area take 1d8 acid damage with a basic Reflex save; on a critical failure, the creature also takes 1 persistent acid damage.', damage: '1d8', range: '30 feet', area: '5-foot burst', action: '2', heightened: "(+2) The damage increases by 1d8 and the splash damage by 1.", heightenStep: 2, heightenDice: '1d8' },
  { name: 'Daze', level: 1, cantrip: true, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You push into the target’s mind and daze it with a mental jolt. The jolt deals 1d6 mental damage, with a basic Will save. If the target critically fails the save, it is also stunned 1.', damage: '1d6', range: '60 feet', target: '1 creature', action: '2', heightened: "(+2) The damage increases by 1d6.", heightenStep: 2, heightenDice: '1d6' },
  { name: 'Detect Magic', level: 1, cantrip: true, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You send out a pulse that registers the presence of magic. You receive no information beyond the presence or absence of magic. You can choose to ignore magic you’re fully aware of, such as the magic items and ongoing spells of you and your allies. You detect illusion magic only if that magic’s effect has a lower rank than the rank of your detect magic spell. However, items that have an illusion aura but aren’t deceptive in appearance (such as an invisibility potion) typically are detected normally.', area: '30-foot emanation', action: '2', heightened: "(3rd) You learn the rank or level of the most powerful magical effect the spell detects, as determined by the GM. (4th) As 3rd rank, but you also pinpoint the source of the highest-rank magic. Like for an imprecise sense, you don't learn the exact location, but can narrow down the source to within a 5-foot cube (or the nearest if larger than that).", heightenAt: [3, 4] },
  { name: 'Electric Arc', level: 1, cantrip: true, tradition: 'Arcane/Primal', book: 'player-core', desc: 'An arc of lightning leaps from one target to another. Each target takes 2d4 electricity damage with a basic Reflex save.', damage: '2d4', range: '30 feet', target: '1 or 2 creatures', action: '2', heightened: "(+1) The damage increases by 1d4.", heightenStep: 1, heightenDice: '1d4' },
  { name: 'Figment', level: 1, cantrip: true, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You create a simple illusory sound or vision. A sound adds the auditory trait to the spell and the sound can’t include intelligible words or elaborate music. A vision adds the visual trait, can be no larger than a 5-foot cube, and is clearly crude and undetailed if viewed from within 15 feet. When you Cast or Sustain the Spell, you can attempt to Create a Diversion with the illusion, gaining a +2 circumstance bonus to your Deception check. If the attempt fails against a creature, that creature disbelieves the figment.', range: '30 feet', action: '2' },
  { name: 'Frostbite', level: 1, cantrip: true, tradition: 'Arcane/Primal', book: 'player-core', desc: 'An orb of biting cold coalesces around your target, freezing its body. The target takes 2d4 cold damage with a basic Fortitude save. On a critical failure, the target also gains weakness 1 to bludgeoning until the start of your next turn.', damage: '2d4', range: '60 feet', target: '1 creature', action: '2', heightened: "(+1) The damage increases by 1d4.", heightenStep: 1, heightenDice: '1d4' },
  { name: 'Gouging Claw', level: 1, cantrip: true, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You temporarily morph your limb into a clawed appendage. Make a melee spell attack roll against your target’s AC. If you hit, you deal your choice of 2d6 slashing damage or 2d6 piercing damage, plus 2 persistent bleed damage. On a critical success, you deal double damage and double bleed damage.', damage: '2d6', range: 'touch', target: '1 creature', action: '2', heightened: "(+1) The damage increases by 1d6 and the persistent bleed damage by 1.", heightenStep: 1, heightenDice: '1d6' },
  { name: 'Ignition', level: 1, cantrip: true, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You snap your fingers and point at a target, which begins to smolder. Make a spell attack roll against the target’s AC, dealing 2d4 fire damage on a hit. If the target is within your melee reach, you can choose to make a melee spell attack with the flame instead of a ranged spell attack, which increases all the spell’s damage dice to d6s. Critical Success The target takes double damage and 1d4 persistent fire damage. Success The target takes full damage.', damage: '2d4', range: '30 feet', target: '1 creature', action: '2', heightened: "(+1) The damage increases by 1d4, or by 1d6 if the target is within your melee reach.", heightenStep: 1, heightenDice: '1d4' },
  { name: 'Light', level: 1, cantrip: true, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You create an orb of light that sheds bright light in a 20-foot radius (and dim light for the next 20 feet) in a color you choose. If you create the light in the same space as a willing creature, you can attach the light to the creature, causing it to float near that creature as it moves. You can Sustain the spell to move the light up to 60 feet; you can attach or detach it from a creature as part of this movement. You can Dismiss the spell. If you Cast the Spell while you already have four light spells active, you must choose one of the existing spells to end.', range: '120 feet', action: '2', heightened: "(4th) The orb sheds light in a 60-foot radius (and dim light for the next 60 feet).", heightenAt: [4] },
  { name: 'Message', level: 1, cantrip: true, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You mouth words quietly, but instead of coming out of your mouth, they’re transferred directly to the ears of the target. While others can’t hear your words any better than if you normally mouthed them, the target can hear your words as if they were standing next to you. The target can give a brief response as a reaction, or as a free action on their next turn if they wish, but they must be able to see you and be within range to do so. If they respond, their response is delivered directly to your ear, just like the original message.', range: '120 feet', target: '1 creature', action: '1', heightened: "(3rd) The spell's range increases to 500 feet.", heightenAt: [3] },
  { name: 'Prestidigitation', level: 1, cantrip: true, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'The simplest magic does your bidding. You can perform simple magical effects for as long as you Sustain the spell. Each time you Sustain the spell, you can choose one of four options. Cook Cool, warm, or flavor 1 pound of nonliving material. Lift Slowly lift an unattended object of light Bulk or less 1 foot off the ground. Make Create a temporary object of negligible Bulk, made of congealed magical substance. The object looks crude and artificial and is extremely fragile—it can’t be used as a tool, weapon, or locus or cost for a spell. Tidy Color, clean, or soil an object of light Bulk or less. You can affect an object of 1 Bulk with 10 rounds of concentration, and a larger object a 1 minute per Bulk. Prestidigitation can’t deal damage or cause adverse conditions. Any actual change to an object (beyond what is noted above) persists only as long as you Sustain the spell.', range: '10 feet', target: '1 object (cook, lift, or tidy only)', action: '2' },
  { name: 'Read Aura', level: 1, cantrip: true, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You focus on the target object, opening your mind to perceive magical auras. When the casting is complete, you know whether that item is magical. You or anyone you advise about the aura gains a +2 circumstance bonus to Identify Magic on the item. If the object is illusory, you detect this only if the effect’s rank is lower than the rank of your read aura spell.', range: '30 feet', target: '1 object', heightened: "(3rd) You can target up to 10 objects. (6th) You can target any number of objects.", heightenAt: [3, 6] },
  { name: 'Shield', level: 1, cantrip: true, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You raise a magical shield of force. This counts as using the Raise a Shield action, giving you a +1 circumstance bonus to AC until the start of your next turn, but it doesn’t require a hand to use. While the spell is in effect, you can use the Shield Block reaction with your magic shield. The shield has Hardness 5. You can use the spell’s reaction to reduce damage from any spell or magical effect, even if it doesn’t deal physical damage. After you use Shield Block, the spell ends and you can’t cast it again for 10 minutes.', action: '1', heightened: '(+2) The shield’s Hardness increases by 5.', heightenStep: 2 },
  { name: 'Sigil', level: 1, cantrip: true, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You harmlessly place your unique magical sigil, which is about 1 square inch in size, on the targeted creature or object. The mark can be visible or invisible, and you can change it from one state to another by using an Interact action to touch the target. The mark can be scrubbed or scraped off with 5 minutes of work. If it’s on a creature, it fades naturally over the course of a week. The time before the mark fades increases depending on your heightened rank.', range: 'touch', target: '1 creature or object', action: '2', heightened: "(3rd) The sigil instead fades after 1 month. (5th) The sigil instead fades after 1 year. (7th) The sigil never fades.", heightenAt: [3, 5, 7] },
  { name: 'Summon Instrument', level: 1, cantrip: true, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You materialize a handheld musical instrument in your grasp. The instrument is typical for its type, but it plays for only you. It vanishes when the spell ends. If you cast summon instrument again, any instrument you previously summoned disappears.', action: '3', heightened: "(5th) The instrument is instead a virtuoso handheld instrument.", heightenAt: [5] },
  { name: 'Tangle Vine', level: 1, cantrip: true, tradition: 'Arcane/Primal', book: 'player-core', desc: 'A vine appears from thin air, flicking from your hand and lashing itself to the target. Attempt a spell attack roll against the target. Critical Success The target gains the immobilized condition and takes a –10-foot circumstance penalty to its Speeds for 1 round. It can attempt to Escape against your spell DC to remove the penalty and the immobilized condition. Success The target takes a –10-foot circumstance penalty to its Speeds for 1 round. It can attempt to Escape against your spell DC to remove the penalty. Failure The target is unaffected.', range: '30 feet', target: '1 creature', action: '2', heightened: "(2nd) The effects last for 2 rounds. (4th) The effects last for 1 minute.", heightenAt: [2, 4] },
  { name: 'Telekinetic Hand', level: 1, cantrip: true, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You create a floating, magical hand, either invisible or ghostlike, that grasps the target object and levitates it slowly up to 20 feet in any direction. When you Sustain the spell, you can move the object an additional 20 feet. If the object is in the air when the spell ends, the object falls.', range: '30 feet', target: '1 unattended object of light Bulk or less', action: '2', heightened: "(3rd) You can target an unattended object with a Bulk of 1 or less. (5th) The range increases to 60 feet, and you can target an unattended object with a Bulk of 1 or less. (7th) The range increases to 60 feet, and you can target an unattended object with a Bulk of 2 or less.", heightenAt: [3, 5, 7] },
  { name: 'Telekinetic Projectile', level: 1, cantrip: true, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You hurl a loose, unattended object that is within range and that has 1 Bulk or less at the target. Make a spell attack roll against the target’s AC. If you hit, you deal 2d6 bludgeoning, piercing, or slashing damage—as appropriate for the object you hurled. No specific traits or magic properties of the hurled item affect the attack or the damage. Critical Success You deal double damage. Success You deal full damage.', damage: '2d6', range: '30 feet', target: '1 creature', action: '2', heightened: "(+1) The damage increases by 1d6.", heightenStep: 1, heightenDice: '1d6' },
  { name: 'Void Warp', level: 1, cantrip: true, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You call upon the Void to harm life force. The target takes 2d4 void damage with a basic Fortitude save. On a critical failure, the target is also enfeebled 1 until the start of your next turn.', damage: '2d4', range: '30 feet', target: '1 living creature', action: '2', heightened: "(+1) The damage increases by 1d4.", heightenStep: 1, heightenDice: '1d4' },
  { name: 'Divine Lance', level: 1, cantrip: true, tradition: 'Divine', book: 'player-core', desc: 'You unleash a beam of divine energy. Make a ranged spell attack against the target’s AC. On a hit, the target takes 2d4 spirit damage (double damage on a critical hit).', damage: '2d4', range: '60 feet', target: '1 creature', action: '2', heightened: "(+1) The damage increases by 1d4.", heightenStep: 1, heightenDice: '1d4' },
  { name: 'Forbidding Ward', level: 1, cantrip: true, tradition: 'Divine/Occult', book: 'player-core', desc: 'You ward an ally against the attacks and hostile spells from the target enemy. The target ally gains a +1 status bonus to Armor Class and saving throws against the target enemy’s attacks, spells, and other effects.', range: '30 feet', target: '1 ally and 1 enemy', action: '2', heightened: "(6th) The status bonus increases to +2.", heightenAt: [6] },
  { name: 'Guidance', level: 1, cantrip: true, tradition: 'Divine/Occult/Primal', book: 'player-core', desc: 'You ask for the guidance of supernatural entities, granting the target a +1 status bonus to one attack roll, Perception check, saving throw, or skill check the target attempts before the duration ends. The target chooses which roll to use the bonus on before rolling. If the target uses the bonus, the spell ends. Either way, the target is then temporarily immune for 1 hour.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Know the Way', level: 1, cantrip: true, tradition: 'Divine/Occult/Primal', book: 'player-core', desc: 'In your mind’s eye, you magically reorient yourself. You immediately know which direction is north (if it exists at your current location), and you can choose a location you were at within the last 24 hours and learn what direction it lies.', action: '2', heightened: "(3rd) You can choose a location you were at within the last week. (7th) You can choose a location you were at regardless of how long ago you were there.", heightenAt: [3, 7] },
  { name: 'Stabilize', level: 1, cantrip: true, tradition: 'Divine/Primal', book: 'player-core', desc: 'Life energy shuts death’s door. The target loses the dying condition, though it remains unconscious at 0 Hit Points.', range: '30 feet', target: '1 dying creature', action: '2' },
  { name: 'Vitality Lash', level: 1, cantrip: true, tradition: 'Divine/Primal', book: 'player-core', desc: 'You demolish the target’s corrupted essence with energy from Creation’s Forge. You deal 2d6 vitality damage with a basic Fortitude save. If the creature critically fails the save, it is also enfeebled 1 until the start of your next turn.', damage: '2d6', range: '30 feet', target: '1 creature that is undead or otherwise has void healing', action: '2', heightened: "(+1) The damage increases by 1d6.", heightenStep: 1, heightenDice: '1d6' },
  // 1st rank
  { name: 'Air Bubble', level: 1, tradition: 'Arcane/Divine/Primal', book: 'player-core', desc: 'A bubble of pure air appears around the target’s head, allowing it to breathe normally. The effect ends as soon as the target returns to an environment where it can breathe normally.', range: '60 feet', target: 'the triggering creature', action: 'R' },
  { name: 'Alarm', level: 1, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You ward an area to alert you when creatures enter without your permission. When you cast alarm, select a password. Whenever a Small or larger corporeal creature enters the spell’s area without speaking the password, alarm sends your choice of a mental alert (in which case the spell gains the mental trait) or an audible alarm with the sound and volume of a hand bell (in which case the spell gains the auditory trait). Either option automatically awakens you, and the bell allows each creature in the area to attempt a DC 15 Perception check to wake up. A creature aware of the alarm must succeed at a Stealth check against the spell’s DC or trigger the spell when moving into the area.', range: 'touch', area: '20-foot burst', heightened: "(3rd) You can specify a trigger for which types of creatures sound the alarm spell, as described in Setting Triggers on page 303.", heightenAt: [3] },
  { name: 'Ant Haul', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You reinforce the target’s musculoskeletal system to bear more weight. The target can carry 3 more Bulk than normal before becoming encumbered and up to a maximum of 6 more Bulk.', range: 'touch', target: '1 creature', action: '2' },
  { name: 'Bane', level: 1, tradition: 'Divine/Occult', book: 'player-core', desc: 'You fill the minds of your enemies with doubt. Enemies in the area must succeed at a Will save or take a –1 status penalty to attack rolls as long as they are in the area. Once per round on subsequent turns, you can Sustain the spell to increase the emanation’s radius by 10 feet and force enemies in the area that weren’t yet affected to attempt another saving throw. Bane can counteract bless.', target: 'enemies in the area', area: '10-foot emanation', action: '2' },
  { name: 'Bless', level: 1, tradition: 'Divine/Occult', book: 'player-core', desc: 'Blessings from beyond help your companions strike true. You and your allies gain a +1 status bonus to attack rolls while within the emanation. Once per round on subsequent turns, you can Sustain the spell to increase the emanation’s radius by 10 feet. Bless can counteract bane.', target: 'you and allies in the area', area: '15-foot emanation', action: '2' },
  { name: 'Breathe Fire', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'A gout of flame sprays from your mouth. You deal 2d6 fire damage to creatures in the area with a basic Reflex save.', damage: '2d6', area: '15-foot cone', action: '2', heightened: "(+1) The damage increases by 2d6.", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Charm', level: 1, tradition: 'Arcane/Occult/Primal', book: 'player-core', desc: 'To the target, your words are honey and your visage seems bathed in a dreamy haze. It must attempt a Will save, with a +4 circumstance bonus if you or your allies recently threatened it or used hostile actions against it. You can Dismiss the spell. If you use hostile actions against the target, the spell ends. When the spell ends, the target doesn’t necessarily realize it was charmed unless its friendship with you or the actions you convinced it to take clash with its expectations, meaning you could potentially convince the target to continue being your friend via mundane means. Critical Success The target is unaffected and aware you tried to charm it. Success The target is unaffected but thinks your spell was something harmless instead of charm, unless it identifies the spell. Failure The target’s attitude becomes friendly toward you. If it was friendly, it becomes helpful. It can’t use hostile actions against you. Critical Failure The target’s attitude becomes helpful toward you, and it can’t use hostile actions against you.', range: '30 feet', target: '1 creature', action: '2', heightened: "(4th) The duration lasts until your next daily preparations. (8th) The duration lasts until your next daily preparations, and you can target up to 10 creatures.", heightenAt: [4, 8] },
  { name: 'Cleanse Cuisine', level: 1, tradition: 'Divine/Primal', book: 'player-core', desc: 'You transform all food and beverages in the area into delicious fare, changing water into wine or another fine beverage, or enhancing the food’s taste and ingredients to make it a gourmet treat. You can also choose to remove all toxins and contaminations from the food. This spell doesn’t prevent future contamination, natural decay, or spoilage, nor does it make the food any more nutritious.', range: '10 feet', target: '1 cubic foot', action: '2', heightened: "(+2) Add another cubic foot to the area, which must be contiguous with the rest.", heightenStep: 2 },
  { name: 'Command', level: 1, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You shout a command that’s hard to ignore. You can command the target to approach you, run away (as if it had the fleeing condition), release what it’s holding, drop prone, or stand in place. It can’t Delay or take any reactions until it has obeyed your command. The effects depend on the target’s Will save. Success The creature is unaffected. Failure The creature must spend the first action on its next turn to obey your command. Critical Failure The target must use all its actions on its next turn to obey your command.', range: '30 feet', target: '1 creature', action: '2', heightened: "(5th) You can target up to 10 creatures.", heightenAt: [5] },
  { name: 'Create Water', level: 1, tradition: 'Arcane/Divine/Primal', book: 'player-core', desc: 'As you cup your hands, water begins to flow forth from them. You create 2 gallons of water. If no one drinks it, it evaporates after 1 day.', range: '0 feet', action: '2' },
  { name: 'Detect Poison', level: 1, tradition: 'Divine/Primal', book: 'player-core', desc: 'You detect whether a creature is venomous or poisonous, or if an object is poison or has been poisoned. You do not ascertain whether the target is poisonous in multiple ways, nor do you learn the type or types of poison. Certain substances, like lead and alcohol, are poisons and so mask other poisons.', range: '30 feet', target: '1 object or creature', action: '2', heightened: "(2nd) You learn the number and types of poison.", heightenAt: [2] },
  { name: 'Disguise Magic', level: 1, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You alter how an item’s or spell’s magical aura appears to effects like detect magic. You can hide the auras entirely, have an item register as a common item of lower level, or make a spell register as a common spell of the same or lower rank. You can Dismiss the spell. A caster using detect magic or read aura of a higher rank than disguise magic can attempt to disbelieve the illusion using the skill matching the tradition of the spell (Arcana for arcane, Religion for divine, Occultism for occult, or Nature for primal). Further attempts by the same caster get the same result as the initial check to disbelieve.', range: '30 feet', target: '1 item or spell effect', heightened: "(2nd) You can Cast this Spell on a creature, disguising all items and spell effects on it.", heightenAt: [2] },
  { name: 'Dizzying Colors', level: 1, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You unleash a swirling multitude of colors that overwhelms creatures based on their Will saves. Critical Success The creature is unaffected. Success The creature is dazzled for 1 round. Failure The creature is stunned 1, blinded for 1 round, and dazzled for 1 minute. Critical Failure The creature is stunned for 1 round and blinded for 1 minute.', area: '15-foot cone', action: '2' },
  { name: 'Enfeeble', level: 1, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You sap the target’s strength, depending on its Fortitude save. Critical Success The target is unaffected. Success The target is enfeebled 1 until the start of your next turn. Failure The target is enfeebled 2 for 1 minute. Critical Failure The target is enfeebled 3 for 1 minute.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Fear', level: 1, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You plant fear in the target; it must attempt a Will save. Critical Success The target is unaffected. Success The target is frightened 1. Failure The target is frightened 2. Critical Failure The target is frightened 3 and fleeing for 1 round.', range: '30 feet', target: '1 creature', action: '2', heightened: "(3rd) You can target up to five creatures.", heightenAt: [3] },
  { name: 'Fleet Step', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You gain a +30-foot status bonus to your Speed.', action: '2' },
  { name: 'Force Barrage', level: 1, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You fire a shard of solidified magic toward a creature that you can see. It automatically hits and deals 1d4+1 force damage. For each additional action you use when Casting the Spell, increase the number of shards you shoot by one, to a maximum of three shards for 3 actions. You choose the target for each shard individually. If you shoot more than one shard at the same target, combine the damage before applying bonuses or penalties to damage, resistances, weaknesses, and so forth.', damage: '1d4+1', range: '120 feet', target: '1 creature', action: '1-3', heightened: "(+2) You fire one additional shard with each action you spend.", heightenStep: 2 },
  { name: 'Gentle Landing', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You raise a magical updraft to arrest a fall. The target’s fall slows to 60 feet per round, and the portion of the fall during the spell’s duration doesn’t count when calculating falling damage. If the target reaches the ground while the spell is in effect, it takes no damage from the fall. The spell ends as soon as the target lands.', range: '60 feet', target: '1 falling creature', action: 'R' },
  { name: 'Goblin Pox', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Your touch afflicts the target with goblin pox, an irritating allergenic rash. The target must attempt a Fortitude save. Critical Success The target is unaffected. Success The target is sickened 1. Failure The target is afflicted with goblin pox at stage 1. Critical Failure The target is afflicted with goblin pox at stage 2. Goblin Pox (disease) Level 1; Creatures that have the goblin trait and goblin dogs are immune; Stage 1 sickened 1 (1 round); Stage 2 sickened 1 and slowed 1 (1 round); Stage 3 sickened 1 and the creature can’t reduce its sickened value below 1 (1 day)', range: 'touch', target: '1 creature', action: '2' },
  { name: 'Grease', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You conjure grease, choosing an area or target. Area All solid ground in the area is covered with grease. Each creature standing on the greasy surface must succeed at a Reflex save or an Acrobatics check against your spell DC or fall prone. Creatures using an action to move onto the greasy surface during the spell’s duration must attempt either a Reflex save or an Acrobatics check to Balance. A creature that Steps or Crawls doesn’t have to attempt a check or save. Target If you Cast the Spell on an unattended object, anyone trying to pick up the object must succeed at an Acrobatics check or Reflex save against your spell DC to do so. If you target an attended object, the creature that has the object must attempt an Acrobatics check or Reflex save. On a failure, the holder or wielder takes a –2 circumstance penalty to all checks that involve using the object; on a critical failure, the holder or wielder releases the item. The object lands in an adjacent square of the GM’s choice. If you Cast this Spell on a worn object, the wearer gains a +2 circumstance bonus to Fortitude saves against attempts to grapple them.', range: '30 feet', target: '1 object of Bulk 1 or less', action: '2' },
  { name: 'Grim Tendrils', level: 1, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Tendrils of darkness curl out from your fingertips and race through the air. You deal 2d4 void damage and 1 persistent bleed damage to living creatures in the line. Each living creature in the line must attempt a Fortitude save. Critical Success The creature is unaffected. Success The creature takes half the void damage and no persistent bleed damage. Failure The creature takes full damage. Critical Failure The creature takes double void damage and double persistent bleed damage.', damage: '2d4', area: '30-foot line', action: '2', heightened: "(+1) The void damage increases by 2d4, and the persistent bleed damage increases by 1.", heightenStep: 1, heightenDice: '2d4' },
  { name: 'Gust of Wind', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'A violent wind issues forth from your palm, blowing from the point where you are when you Cast the Spell to the line’s opposite end. The wind extinguishes small non-magical fires, disperses fog and mist, blows objects of light Bulk or less around, and pushes larger objects. Large or smaller creatures in the area must attempt a Fortitude save. Large or smaller creatures that later move into the gust must attempt the save on entering. Critical Success The creature is unaffected. Success The creature can’t move against the wind. Failure The creature is knocked prone. If it was flying, it takes the effects of critical failure instead. Critical Failure The creature is pushed 30 feet in the wind’s direction, knocked prone, and takes 2d6 bludgeoning damage.', damage: '2d6', area: '60-foot line', action: '2' },
  { name: 'Harm', level: 1, tradition: 'Divine', book: 'player-core', font: 'harm', desc: 'You channel void energy to harm the living or heal the undead. If the target is a living creature, you deal 1d8 void damage to it, and it gets a basic Fortitude save. If the target is a willing undead creature, you restore that amount of Hit Points. The number of actions you spend when Casting this Spell determines its targets, range, area, and other parameters. 1 Action The spell has a range of touch. 2 Actions (concentrate) The spell has a range of 30 feet. If you’re healing an undead creature, increase the Hit Points restored by 8. 3 Actions (concentrate) You disperse void energy in a 30-foot emanation. This targets all living and undead creatures in the area.', damage: '1d8', range: 'varies', target: '1 living creature or 1 willing undead creature', action: '1-3', heightened: "(+1) The amount of healing or damage increases by 1d8, and the extra healing for the 2-action version increases by 8.", heightenStep: 1, heightenDice: '1d8' },
  { name: 'Heal', level: 1, tradition: 'Divine/Primal', book: 'player-core', font: 'heal', desc: 'You channel vital energy to heal the living or damage the undead. If the target is a willing living creature, you restore 1d8 Hit Points. If the target is undead, you deal that amount of vitality damage to it, and it gets a basic Fortitude save. The number of actions you spend when Casting this Spell determines its targets, range, area, and other parameters. 1 Action The spell has a range of touch. 2 Actions (concentrate) The spell has a range of 30 feet. If you’re healing a living creature, increase the Hit Points restored by 8. 3 Actions (concentrate) You disperse vital energy in a 30-foot emanation. This targets all living and undead creatures in the burst.', damage: '1d8', range: 'varies', target: '1 willing living creature or 1 undead', action: '1-3', heightened: "(+1) The amount of healing or damage increases by 1d8, and the extra healing for the 2-action version increases by 8.", heightenStep: 1, heightenDice: '1d8' },
  { name: 'Hydraulic Push', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You call forth a powerful blast of pressurized water that bludgeons the target and knocks it back. Make a ranged spell attack roll. Critical Success The target takes 6d6 bludgeoning damage and is knocked back 10 feet. Success The target takes 3d6 bludgeoning damage and is knocked back 5 feet.', damage: '3d6', range: '60 feet', target: '1 creature or unattended object', action: '2', heightened: "(+1) The bludgeoning damage increases by 2d6.", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Ill Omen', level: 1, tradition: 'Occult', book: 'player-core', desc: 'The target is struck with misfortune, which throws it off balance. The target must attempt a Will save. Success The target is unaffected. Failure The first time during the duration that the target attempts an attack roll or skill check, it must roll twice and use the worse result. Critical Failure Every time during the duration that the target attempts an attack roll or skill check, it must roll twice and use the worse result.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Illusory Disguise', level: 1, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You create an illusion that causes the target to appear as another creature of the same body shape, and with roughly similar height (within 6 inches) and weight (within 50 pounds). The disguise is typically good enough to hide their identity, but not to impersonate a specific individual. The spell changes their appearance and voice, but not mannerisms. You can change the appearance of its clothing and worn items, such as making its armor look like a dress. Held items are unaffected, and any worn item removed from the creature returns to its true appearance. Casting illusory disguise counts as setting up a disguise for the Impersonate use of Deception; it ignores any circumstance penalties the target might take for disguising itself as a dissimilar creature, gives a +4 status bonus to Deception checks to prevent others from seeing through the disguise, and lets the target add its level to such Deception checks even if untrained. You can Dismiss this spell.', range: '30 feet', target: '1 willing creature', action: '2', heightened: "(3rd) The target can appear as any creature of the same size, even a specific individual. You must have seen an individual to replicate its appearance, and must have heard its voice to replicate its voice. (4th) You can target up to 10 willing creatures. If you target multiple creatures, you can choose a different disguise for each target, but none can impersonate a specific individual. You can Dismiss each disguise individually or all collectively. (7th) As 4th, but you can choose disguises that impersonate specific individuals. You must have seen an individual to replicate its appearance, and must have heard its voice to replicate its voice.", heightenAt: [3, 4, 7] },
  { name: 'Illusory Object', level: 1, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You create an illusory visual image of a stationary object. The entire image must fit within the spell’s area. The object appears to animate naturally, but it doesn’t make sounds or generate smells. For example, water would appear to pour down an illusory waterfall, but it would be silent. Any creature that touches the image or uses the Seek action to examine it can attempt to disbelieve your illusion.', range: '500 feet', area: '20-foot burst', action: '2', heightened: "(2nd) Your image makes appropriate sounds, generates normal smells, and feels right to the touch. The spell gains the auditory and olfactory traits. The duration increases to 1 hour. (5th) As the 2nd-rank version, but the duration is unlimited.", heightenAt: [2, 5] },
  { name: 'Infuse Vitality', level: 1, tradition: 'Divine', book: 'player-core', desc: 'You empower attacks with vital energy. The number of targets is equal to the number of actions you spent casting this spell. Each target’s unarmed and weapon Strikes deal an extra 1d4 vitality damage. (This damage typically damages only undead.) If you have the holy trait, you can add that trait to this spell and to the Strikes affected by the spell.', range: '30 feet', target: '1 to 3 willing creatures', action: '1-3', heightened: "(3rd) The damage increases to 2d4 damage. (5th) The damage increases to 3d4 damage.", heightenAt: [3, 5] },
  { name: 'Item Facade', level: 1, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You make the target object look and feel as though it were in much better or worse physical condition. When you Cast this Spell, decide whether you want to make the object look decrepit or perfect. An item made to look decrepit appears broken and shoddy. An intact item made to look better appears as though it’s brand new and highly polished or well maintained. A broken item appears to be intact and functional. Destroyed items can’t be affected by this spell. A creature that Interacts with the item can attempt to disbelieve the illusion.', range: 'touch', target: '1 object no more than 10 feet by 10 feet by 10 feet', action: '2', heightened: "(2nd) The duration is 24 hours. (3rd) The duration is unlimited.", heightenAt: [2, 3] },
  { name: 'Jump', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Your legs surge with strength, ready to leap high and far. You jump 30 feet in any direction without touching the ground. You must land on a space of solid ground within 30 feet of you, or else you fall after using your next action.', action: '1', heightened: "(3rd) The range becomes touch, the target changes to one touched creature, and the duration becomes 1 minute, allowing the target to jump as described whenever it takes the Leap action.", heightenAt: [3] },
  { name: 'Lock', level: 1, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'The target’s latch mechanism clinks shut, held fast by unseen magical wards. When you magically lock a target, you set an Athletics and Thievery DC to open it equal to your spell DC or the base lock DC with a +4 status bonus, whichever is higher. Any key or combination that once opened a lock affected by this spell does not do so for the duration of the spell, though the key or combination does grant a +4 circumstance bonus to checks to open the door. If the target is opened, the spell ends. Assuming the target is not barred or locked in some additional way, you can unlock and open it with an Interact action during which you touch the target. This does not end the spell. You can Dismiss this spell at any time and from any distance.', range: 'touch', target: '1 lock, or a door or container with a latch', action: '2', heightened: "(2nd) The duration is unlimited, but you must expend 6 gp worth of precious metals as an additional cost.", heightenAt: [2] },
  { name: 'Mending', level: 1, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You repair the target item. You restore 5 Hit Points per spell rank to the target, potentially removing the broken condition if this repairs it past the item’s Broken Threshold. You can’t replace lost pieces or repair an object that’s been completely destroyed.', range: 'touch', target: 'non-magical object of light Bulk or less', heightened: "(2nd) You can target a non-magical object of 1 Bulk or less. (3rd) You can target a non-magical object of 2 Bulk or less, or a magical object of 1 Bulk or less.", heightenAt: [2, 3] },
  { name: 'Mindlink', level: 1, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You link your mind to the target’s mind and mentally impart to that target an amount of information in an instant that could otherwise be communicated in 10 minutes.', range: 'touch', target: '1 willing creature', action: '2' },
  { name: 'Mystic Armor', level: 1, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You ward yourself with shimmering magical energy, gaining a +1 item bonus to AC and a maximum Dexterity modifier of +5. While wearing mystic armor, you use your unarmored proficiency to calculate your AC.', action: '2', heightened: "(4th) You gain a +1 item bonus to saving throws. (6th) The item bonus to AC increases to +2, and you gain a +1 item bonus to saving throws. (8th) The item bonus to AC increases to +2, and you gain a +2 item bonus to saving throws. (10th) The item bonus to AC increases to +3, and you gain a +3 item bonus to saving throws.", heightenAt: [4, 6, 8, 10] },
  { name: 'Pest Form', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You transform into the battle form of a Tiny animal, such as a cat, insect, lizard, or rat. You can decide the specific type of animal (such as a rat or praying mantis), but this has no effect on your Size or statistics. While in this form, you gain the animal trait, and you can’t make Strikes. You can Dismiss the spell. You gain the following statistics and abilities: AC = 15 + your level. Ignore your armor’s check penalty and Speed reduction. Speed 20 feet. Weakness 5 to physical damage. (If you take physical damage in this form, you take 5 additional damage.) Low-light vision and imprecise scent 30 feet. Acrobatics and Stealth modifiers of +10, unless your own is higher; Athletics modifier –4.', action: '2', heightened: "(4th) You can turn into a flying creature, such as a bird, which grants you a fly Speed of 20 feet.", heightenAt: [4] },
  { name: 'Pet Cache', level: 1, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You open your cloak or create a gap with your hands, drawing the target into a pocket dimension just large enough for its basic comfort. No other creature can enter this extradimensional space, and the target can bring along objects only if they were designed to be worn by a creature of its kind. The space has enough air, food, and water to sustain the target for the duration. You can Dismiss the spell. The spell also ends if you die or enter an extradimensional space. When the spell ends, the target reappears in the nearest unoccupied space (outside of any extradimensional space you may have entered).', range: 'touch', target: '1 willing creature that is your companion', action: '1' },
  { name: 'Phantasmal Minion', level: 1, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You summon a phantasmal minion. The minion is roughly the shape of a humanoid. You can choose to have it be invisible or have an ephemeral appearance, but it’s obviously a magical effect, not a real creature.', range: '60 feet', action: '3' },
  { name: 'Phantom Pain', level: 1, tradition: 'Occult', book: 'player-core', desc: 'Illusory pain wracks the target, dealing 2d4 mental damage and 1d4 persistent mental damage with a Will save. Critical Success The target is unaffected. Success The target takes full initial damage but no persistent damage, and the spell ends immediately. Failure The target takes full initial and persistent damage, and the target is sickened 1. If the target recovers from being sickened, the persistent damage ends and the spell ends. Critical Failure As failure, but the target is sickened 2.', damage: '2d4', range: '30 feet', target: '1 creature', action: '2', heightened: "(+1) The damage increases by 2d4 and the persistent damage by 1d4.", heightenStep: 1, heightenDice: '2d4' },
  { name: 'Protection', level: 1, tradition: 'Divine/Occult', book: 'player-core', desc: 'You ward a creature against harm. The target gains a +1 status bonus to Armor Class and saving throws.', range: 'touch', target: '1 willing creature', action: '2', heightened: "(3rd) You can choose to have the benefits also affect all your allies in a 10-foot emanation around the target.", heightenAt: [3] },
  { name: 'Pummeling Rubble', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'A spray of heavy rocks flies through the air in front of you. The rubble deals 2d4 bludgeoning damage to each creature in the area. Each creature must attempt a Reflex save. Critical Success The creature is unaffected. Success The creature takes half damage. Failure The creature takes full damage and is pushed 5 feet away from you. Critical Failure The creature takes double damage and is pushed 10 feet away from you.', damage: '2d4', area: '15-foot cone', action: '2', heightened: "(+1) The damage increases by 2d4.", heightenStep: 1, heightenDice: '2d4' },
  { name: 'Runic Body', level: 1, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'Glowing runes appear on the target’s body. All its unarmed attacks become +1 striking unarmed attacks, gaining a +1 item bonus to attack rolls and increasing the number of damage dice to two.', range: 'touch', target: '1 willing creature', action: '2', heightened: "(6th) The unarmed attacks are +2 greater striking. (9th) The unarmed attacks are +3 major striking.", heightenAt: [6, 9] },
  { name: 'Runic Weapon', level: 1, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'The weapon glimmers with magic as temporary runes carve down its length. The target becomes a +1 striking weapon, gaining a +1 item bonus to attack rolls and increasing the number of weapon damage dice to two.', range: 'touch', target: '1 weapon that is unattended or wielded by a willing creature', action: '2', heightened: "(6th) The weapon is +2 greater striking. (9th) The weapon is +3 major striking.", heightenAt: [6, 9] },
  { name: 'Sanctuary', level: 1, tradition: 'Divine/Occult', book: 'player-core', desc: 'You ward a creature with protective energy that deters attacks. Creatures attempting to attack the target must attempt a Will save each time. If the target uses a hostile action, the spell ends. Critical Success Sanctuary ends. Success The creature can attempt its attack and any other attacks against the target this turn. Failure The creature can’t attack the target and wastes the action. It can’t attempt further attacks against the target this turn. Critical Failure The creature wastes the action and can’t attempt to attack the target for the rest of sanctuary’s duration.', range: 'touch', target: '1 creature', action: '2' },
  { name: 'Sleep', level: 1, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Each creature in the area becomes drowsy, possibly nodding off. A creature that falls unconscious from this spell doesn’t fall prone or release what it’s holding. This spell doesn’t prevent creatures from waking up due to a successful Perception check, limiting its utility in combat. Critical Success The creature is unaffected. Success The creature takes a –1 status penalty to Perception checks for 1 round. Failure The creature falls unconscious. If it’s still unconscious after 1 minute, it wakes up automatically. Critical Failure The creature falls unconscious. If it’s still unconscious after 1 hour, it wakes up automatically.', range: '30 feet', area: '5-foot burst', action: '2', heightened: "(4th) The creatures fall unconscious for 1 round on a failure or 1 minute on a critical failure. They fall prone and release what they're holding, and they can't attempt Perception checks to wake up. When the duration ends, the creature is sleeping normally instead of automatically waking up.", heightenAt: [4] },
  { name: 'Soothe', level: 1, tradition: 'Occult', book: 'player-core', desc: 'You grace the target’s mind, boosting its mental defenses and healing its wounds. The target regains 1d10+4 Hit Points when you Cast the Spell and gains a +2 status bonus to saves against mental effects for the duration.', range: '30 feet', target: '1 willing creature', action: '2', heightened: "(+1) The amount of healing increases by 1d10+4.", heightenStep: 1 },
  { name: 'Spider Sting', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You magically duplicate a spider’s venomous sting. You deal 1d4 piercing damage to the touched creature and afflict it with spider venom. The target must attempt a Fortitude save. Critical Success The target is unaffected. Success The target takes 1d4 poison damage. Failure The target is afflicted with spider venom at stage 1. Critical Failure The target is afflicted with spider venom at stage 2. Spider Venom (poison) Level 1; Maximum Duration 4 rounds; Stage 1 1d4 poison damage and enfeebled 1 (1 round); Stage 2 1d4 poison damage and enfeebled 2 (1 round)', damage: '1d4', range: 'touch', target: '1 creature', action: '2' },
  { name: 'Spirit Link', level: 1, tradition: 'Divine/Occult', book: 'player-core', desc: 'You form a spiritual link with another creature, taking in its pain. When you Cast this Spell and at the start of each of your turns, if the target is below maximum Hit Points, it regains 2 Hit Points (or the difference between its current and maximum Hit Points, if that’s lower). You lose as many Hit Points as the target regained. This is a spiritual transfer, so no effects apply that would increase the Hit Points the target regains or decrease the Hit Points you lose. This transfer also ignores any temporary Hit Points you or the target have. Since this effect doesn’t involve vitality or void energy, spirit link works even if you or the target is undead. While the duration persists, you gain no benefit from regeneration or fast healing. You can Dismiss this spell, and if you’re ever at 0 Hit Points, spirit link ends automatically.', range: '30 feet', target: '1 willing creature', action: '2', heightened: "(+1) The number of Hit Points transferred each time increases by 2.", heightenStep: 1 },
  { name: 'Summon Animal', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You summon a creature that has the animal trait and whose level is –1 to fight for you.', range: '30 feet', action: '3', heightened: "(2nd) Level 1. (3rd) Level 2. (4th) Level 3. (5th) Level 5. (6th) Level 7. (7th) Level 9. (8th) Level 11. (9th) Level 13. (10th) Level 15.", heightenAt: [2, 3, 4, 5, 6, 7, 8, 9, 10] },
  { name: 'Summon Construct', level: 1, tradition: 'Arcane', book: 'player-core', desc: 'You summon a creature that has the construct trait and whose level is –1 to fight for you.', range: '30 feet', action: '3', heightened: "(2nd) Level 1. (3rd) Level 2. (4th) Level 3. (5th) Level 5. (6th) Level 7. (7th) Level 9. (8th) Level 11. (9th) Level 13. (10th) Level 15.", heightenAt: [2, 3, 4, 5, 6, 7, 8, 9, 10] },
  { name: 'Summon Fey', level: 1, tradition: 'Occult/Primal', book: 'player-core', desc: 'You summon a creature that has the fey trait and whose level is –1 to fight for you.', range: '30 feet', action: '3', heightened: "(2nd) Level 1. (3rd) Level 2. (4th) Level 3. (5th) Level 5. (6th) Level 7. (7th) Level 9. (8th) Level 11. (9th) Level 13. (10th) Level 15.", heightenAt: [2, 3, 4, 5, 6, 7, 8, 9, 10] },
  { name: 'Summon Plant or Fungus', level: 1, tradition: 'Primal', book: 'player-core', desc: 'You summon a creature that has the plant or fungus trait and whose level is –1 to fight for you.', range: '30 feet', action: '3', heightened: "(2nd) Level 1. (3rd) Level 2. (4th) Level 3. (5th) Level 5. (6th) Level 7. (7th) Level 9. (8th) Level 11. (9th) Level 13. (10th) Level 15.", heightenAt: [2, 3, 4, 5, 6, 7, 8, 9, 10] },
  { name: 'Summon Undead', level: 1, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You summon a creature that has the undead trait and whose level is –1 to fight for you.', range: '30 feet', action: '3', heightened: "(2nd) Level 1. (3rd) Level 2. (4th) Level 3. (5th) Level 5. (6th) Level 7. (7th) Level 9. (8th) Level 11. (9th) Level 13. (10th) Level 15.", heightenAt: [2, 3, 4, 5, 6, 7, 8, 9, 10] },
  { name: 'Sure Strike', level: 1, tradition: 'Arcane/Occult', book: 'player-core', desc: 'The next time you make an attack roll before the end of your turn, roll it twice and use the better result. The attack ignores circumstance penalties to the attack roll and any flat check required due to the target being concealed or hidden. You are then temporarily immune to sure strike for 10 minutes.', action: '1' },
  { name: 'Tailwind', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'The wind at your back pushes you to find new horizons. You gain a +10-foot status bonus to your Speed.', action: '2', heightened: "(2nd) The duration increases to 8 hours.", heightenAt: [2] },
  { name: 'Thunderstrike', level: 1, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You call down a tendril of lightning that cracks with thunder, dealing 1d12 electricity damage and 1d4 sonic damage to the target with a basic Reflex save. A target wearing metal armor or made of metal takes a –1 circumstance penalty to its save, and if damaged by the spell is clumsy 1 for 1 round.', damage: '1d12+1d4', range: '120 feet', target: '1 creature', action: '2', heightened: "(+1) The damage increases by 1d12 electricity and 1d4 sonic.", heightenStep: 1, heightenDice: '1d12+1d4' },
  { name: 'Vanishing Tracks', level: 1, tradition: 'Primal', book: 'player-core', desc: 'You obscure the tracks you leave behind. The DC of checks to Track you gains a +4 status bonus or is equal to your spell DC, whichever results in a higher DC.', action: '2', heightened: "(2nd) The duration increases to 8 hours. (4th) The duration increases to 8 hours. The spell has a range of 20 feet and targets up to 10 creatures.", heightenAt: [2, 4] },
  { name: 'Ventriloquism', level: 1, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'Whenever you speak or make any other sound vocally, you can make your vocalization seem to originate from somewhere else within 60 feet, and you can change that apparent location freely as you vocalize. Any creature that hears the sound can attempt to disbelieve your illusion.', action: '2', heightened: "(2nd) The spell's duration increases to 1 hour, and you can also change the tone, quality, and other aspects of your voice. Before a creature can attempt to disbelieve your illusion, it must actively attempt a Perception check or otherwise use actions to interact with the sound.", heightenAt: [2] },
  // 2nd rank
  { name: 'Acid Grip', level: 2, tradition: 'Arcane/Primal', book: 'player-core', desc: 'An ephemeral, taloned hand grips the target, burning it with magical acid. The target takes 2d8 acid damage plus 1d6 persistent acid damage depending on its Reflex save. A creature taking persistent damage from this spell takes a –10-foot status penalty to its Speeds. Critical Success The creature is unaffected. Success The creature takes half damage and no persistent damage, and the claw moves it up to 5 feet in a direction of your choice. Failure The creature takes full damage and persistent damage, and the claw moves it up to 10 feet in a direction of your choice. Critical Failure The creature takes double damage and full persistent damage, and the claw moves it up to 20 feet in a direction of your choice.', damage: '2d8', range: '120 feet', target: '1 creature', action: '2', heightened: "(+2) The initial damage increases by 2d8, and the persistent acid damage increases by 1d6.", heightenStep: 2, heightenDice: '2d8' },
  { name: 'Animal Form', level: 2, tradition: 'Primal', book: 'player-core', desc: 'You call upon primal energy to transform yourself into a Medium animal battle form. When you Cast this Spell, choose a listed battle form. You can decide the specific type of animal (such as lion or snow leopard for cat), but this has no effect on the form’s Size or statistics. While in this form, you gain the animal trait. You can Dismiss the spell. You gain the following statistics and abilities regardless of which animal you choose: AC = 16 + your level. Ignore your armor’s check penalty and Speed reduction. 5 temporary Hit Points. Low-light vision and imprecise scent 30 feet. One or more unarmed melee attacks specific to your battle form, which are the only attacks you can Strike with. You’re trained with them. Your attack modifier is +9, and your damage bonus is +1. These attacks are Strength based (for the purpose of the enfeebled condition, for example). If your unarmed attack bonus is higher, you can use it instead. Athletics modifier of +9, unless your own is higher. You also gain specific abilities based on the animal you choose: Ape Speed 25 feet, climb 20 feet; Melee 1 Action fist, Damage 2d6 bludgeoning. Bear Speed 30 feet; Melee 1 Action jaws, Damage 2d8 piercing; Melee 1 Action claw (agile), Damage 1d8 slashing. Bull Speed 30 feet; Melee 1 Action horn, Damage 2d8 piercing. Canine Speed 40 feet; Melee 1 Action jaws, Damage 2d8 piercing. Cat Speed 40 feet; Melee 1 Action jaws, Damage 2d6 piercing; Melee 1 Action claw (agile), Damage 1d10 slashing. Deer Speed 50 feet; Melee 1 Action antler, Damage 2d6 piercing. Frog Speed 25 feet, swim 25 feet; Melee 1 Action jaws, Damage 2d6 bludgeoning; Melee 1 Action tongue (reach 15 feet), Damage 2d4 bludgeoning. Shark swim 35 feet; Melee 1 Action jaws, Damage 2d8 piercing; breathe underwater but not in air. Snake Speed 20 feet, climb 20 feet, swim 20 feet; Melee 1 Action fangs, Damage 2d4 piercing plus 1d6 poison.', action: '2', heightened: "(3rd) You instead gain 10 temporary HP, AC = 17 + your level, attack modifier +14, damage bonus +5, and Athletics +14. (4th) Your battle form is Large and your attacks have 10-foot reach. You instead gain 15 temporary HP, AC = 18 + your level, attack modifier +16, damage bonus +9, and Athletics +16. (5th) Your battle form is Huge and your attacks have 15-foot reach. You instead gain 20 temporary HP, AC = 18 + your level, attack modifier +18, damage bonus +7 and double the number of damage dice, and Athletics +20.", heightenAt: [3, 4, 5] },
  { name: 'Animal Messenger', level: 2, tradition: 'Primal', book: 'player-core', desc: 'You offer food, and an ordinary Tiny animal within range approaches to eat it. You imprint the image, direction, and distance of an obvious place or landmark well known to you within the animal. You can also attach a small object or note up to light Bulk to it. The animal does its best to reach the destination; if it makes it there, it waits nearby and allows nonhostile creatures to approach and remove the attached object. The spell ends after the message is delivered or after 24 hours, whichever comes first. If there are no Tiny wild animals in range, the spell is lost.', range: '120 feet' },
  { name: 'Augury', level: 2, tradition: 'Divine/Occult', book: 'player-core', desc: 'You gain a vague glimpse of the future. During the casting of this spell, ask about the results of a particular course of action. The spell can predict results up to 30 minutes into the future and reveal the GM’s best guess among the following outcomes: good, bad, mixed (the results will be a mix of good and bad), and nothing (there won’t be particularly good or bad results). The GM rolls a secret DC 6 flat check. On a failure, the result is always “nothing.” This makes it impossible to tell whether a “nothing” result is accurate. If anyone asks about the same topic as the first casting of augury during an additional casting, the GM uses the secret roll result from the first casting. If circumstances change, though, it’s possible to get a different result.' },
  { name: 'Blazing Bolt', level: 2, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You fire a ray of heat and flame. Make a spell attack roll against a single creature. On a hit, the target takes 2d6 fire damage, and on a critical hit, the target takes double damage. For each additional action you use when Casting the Spell, you can fire an additional ray at a different target, to a maximum of three rays targeting three different targets for 3 actions. These attacks each increase your multiple attack penalty, but you don’t increase your multiple attack penalty until after you make all the spell attack rolls for blazing bolt. If you spend 2 or more actions Casting the Spell, the damage increases to 4d6 fire damage on a hit, and it still deals double damage on a critical hit.', range: '60 feet', target: '1 or more creatures', action: '1-3', heightened: "(+1) The damage to each target increases by 1d6 for the 1-action version, or by 2d6 for the 2- and 3-action versions.", heightenStep: 1 },
  { name: 'Blood Vendetta', level: 2, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You curse the target, punishing it for having the audacity to spill your blood. The target takes 2d6 persistent bleed damage and must attempt a Will save. Critical Success The target is unaffected. Success The target takes half the persistent bleed damage. Failure The target takes the full persistent bleed damage. Until the bleeding stops, the target has weakness 1 to piercing and slashing damage. Critical Failure As failure, but the target takes double the persistent bleed damage.', damage: '2d6', range: '30 feet', target: 'The triggering creature', action: 'R', heightened: "(+2) The persistent bleed damage increases by 2d6.", heightenStep: 2, heightenDice: '2d6' },
  { name: 'Blur', level: 2, tradition: 'Arcane/Occult', book: 'player-core', desc: 'The target’s form appears blurry. It becomes concealed. As the nature of this effect still leaves the target’s location obvious, the target can’t use this concealment to Hide or Sneak.', range: 'touch', target: '1 creature', action: '2' },
  { name: 'Calm', level: 2, tradition: 'Divine/Occult', book: 'player-core', desc: 'You forcibly calm creatures in the area, soothing them into a nonviolent state; each creature must attempt a Will save. Critical Success The creature is unaffected. Success Calming urges impose a –1 status penalty to the creature’s attack rolls. Failure Any emotion effects that would affect the creature are suppressed and the creature can’t use hostile actions. If the target is subject to hostility from any other creature, it ceases to be affected by calm. Critical Failure As failure, but hostility doesn’t end the effect.', range: '120 feet', area: '10-foot burst', action: '2' },
  { name: 'Cleanse Affliction', level: 2, tradition: 'Divine/Occult/Primal', book: 'player-core', desc: 'Gentle restorative magic pushes back the effects of toxins and more complex maladies. Choose an affliction on the target, such as a curse, disease, or poison. If it has advanced past stage one, reduce the stage by one. This reduction can be applied only once to a given case of an affliction, with the case ending when it’s completely cured. Although the reduction can’t occur again, heightened versions of this spell attempt to counteract with each casting.', range: 'touch', target: '1 willing creature', action: '2', heightened: "(3rd) Attempt to counteract the affliction if it is a disease or poison. (4th) Attempt to counteract the affliction if it is a curse, disease, or poison.", heightenAt: [3, 4] },
  { name: 'Clear Mind', level: 2, tradition: 'Divine/Occult/Primal', book: 'player-core', desc: 'You drive mental contamination from the target’s mind. Attempt to counteract an effect of your choice imposing one of these conditions on the target: fleeing, frightened, and stupefied. If you failed to counteract the effect but you would have if its counteract rank were 2 lower, instead suppress the effect until the beginning of your next turn. The effect’s duration doesn’t elapse while it’s suppressed. This spell can’t counteract or suppress conditions that are part of curses, diseases, or a natural state of the target.', range: 'touch', target: '1 willing creature', action: '2', heightened: "(4th) Add confused, controlled, and slowed to the list of conditions. (6th) As 4th rank, plus add doomed. (8th) As 4th rank, plus add doomed and stunned.", heightenAt: [4, 6, 8] },
  { name: 'Create Food', level: 2, tradition: 'Arcane/Divine/Primal', book: 'player-core', desc: 'You create enough food to feed six Medium creatures for a day. This food is bland and unappealing, but it is nourishing. After 1 day, if no one has eaten the food, it decays and becomes inedible. Most Small creatures eat one-quarter as much as a Medium creature (one-sixteenth as much for most Tiny creatures), and most Large creatures eat 10 times as much (100 times as much for Huge creatures and so on).', range: '30 feet', heightened: "(4th) You can feed 12 Medium creatures. (6th) You can feed 50 Medium creatures. (8th) You can feed 200 Medium creatures.", heightenAt: [4, 6, 8] },
  { name: 'Darkness', level: 2, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You create a shroud of darkness that prevents light from penetrating or emanating within the area. Light does not enter the area and any non-magical light sources, such as a torch or lantern, do not emanate any light while inside the area, even if their light radius would extend beyond the darkness. This also suppresses magical light of your darkness spell’s rank or lower. Light can’t pass through, so creatures in the area can’t see outside. From outside, it appears as a globe of pure darkness.', range: '120 feet', area: '20-foot burst', action: '3', heightened: "(4th) Even creatures with darkvision (but not greater darkvision) can barely see through the darkness. They treat targets seen through the darkness as concealed.", heightenAt: [4] },
  { name: 'Darkvision', level: 2, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You grant yourself supernatural sight in areas of darkness. You gain darkvision.', action: '2', heightened: "(3rd) The spell's range is touch and it targets 1 willing creature. (5th) The spell's range is touch and it targets 1 willing creature. The duration is until your next daily preparations.", heightenAt: [3, 5] },
  { name: 'Deafness', level: 2, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'The target loses its hearing. It must attempt a Fortitude save, and it is then temporarily immune for 1 minute. Critical Success The target is unaffected. Success The target is deafened for 1 round. Failure The target is deafened for 10 minutes. Critical Failure The target is deafened permanently.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Dispel Magic', level: 2, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You unravel the magic behind a spell or effect. Attempt a counteract check against the target. If you successfully counteract a magic item, it becomes a mundane item of its type for 10 minutes. This doesn’t change the item’s non-magical properties. If the target is an artifact or similar item, you automatically fail.', range: '120 feet', target: '1 spell effect or unattended magic item', action: '2' },
  { name: 'Embed Message', level: 2, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You specify a trigger and a message up to 25 words long. When the specified trigger occurs within 30 feet of the target, illusory text of your message circles the target accompanied by a disembodied voice. You can choose a language you know for the text and speech, and can choose what the voice sounds like. Once the message is completed, the spell ends.', range: 'touch', target: '1 object or willing creature', action: '2', heightened: "(4th) You can add a simple sensory component to emphasize the message, such as an odor, visual effect, or physical sensation. This addition is obviously illusory and part of the message, lasting only while the message is being read. (6th) As 4th rank, but you can choose how many times the spell repeats the message before it ends; there is no limit to the number of repetitions.", heightenAt: [4, 6] },
  { name: 'Enlarge', level: 2, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Bolstered by magical power, the target grows to size Large. Its equipment grows with it but returns to natural size if removed. The creature is clumsy 1. Its reach increases by 5 feet (or by 10 feet if it started out Tiny), and it gains a +2 status bonus to damage rolls on melee Strikes. This spell has no effect on a Large or larger creature.', range: '30 feet', target: '1 willing creature', action: '2', heightened: "(4th) The creature instead grows to size Huge. The status bonus to melee damage is +4 and the creature's reach increases by 10 feet (or 15 feet if the creature started out Tiny). The spell has no effect on a Huge or larger creature. (6th) Choose either the 2nd-rank or 4th-rank version of this spell and apply its effects to up to 10 willing creatures.", heightenAt: [4, 6] },
  { name: 'Entangling Flora', level: 2, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Plants and fungi burst out or quickly grow, entangling creatures. All surfaces in the area are difficult terrain. Each round that a creature starts its turn in the area, it must attempt a Reflex save. On a failure, it takes a –10-foot circumstance penalty to its Speeds until it leaves the area, and on a critical failure, it’s also immobilized for 1 round. Creatures can attempt to Escape to remove these effects.', range: '120 feet', area: '20-foot burst', action: '2' },
  { name: 'Environmental Endurance', level: 2, tradition: 'Arcane/Divine/Primal', book: 'player-core', desc: 'You shield the target against dangerous temperatures. Choose severe cold or heat. The target is protected from the temperature you chose (but not extreme cold or heat).', range: 'touch', target: '1 willing creature', heightened: "(3rd) The target is protected from severe cold and severe heat. (5th) The target is protected from severe cold, severe heat, extreme cold, and extreme heat.", heightenAt: [3, 5] },
  { name: 'Everlight', level: 2, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'The gemstone you touch glows, spreading bright light with a color of your choice in a 20-foot radius (and dim light for the next 20 feet). The spell ends immediately if the gemstone is broken.', range: 'touch', target: 'a gemstone worth 6 gp or more', action: '3' },
  { name: 'False Vitality', level: 2, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You augment your flesh with the energies typically used to manipulate the undead. You gain 10 temporary Hit Points.', action: '2', heightened: "(+1) The temporary Hit Points increase by 3.", heightenStep: 1 },
  { name: 'Floating Flame', level: 2, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You create a fire that burns without fuel and moves to your commands. The flame deals 3d6 fire damage to each creature in the square in which it appears, with a basic Reflex save. When you Sustain this spell, you can levitate the flame up to 10 feet. It then deals damage to each creature whose space it shared at any point during its flight. This uses the same damage and save, and you roll the damage once each time you Sustain. A given creature can take damage from floating flame only once per round.', damage: '3d6', range: '30 feet', area: '5-foot square', action: '2', heightened: "(+1) The damage increases by 1d6.", heightenStep: 1, heightenDice: '1d6' },
  { name: 'Gecko Grip', level: 2, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Tiny clinging hairs sprout across the creature’s hands and feet, offering purchase on nearly any surface. The target gains a climb Speed equal to its Speed.', range: 'touch', target: '1 creature', action: '2', heightened: "(5th) The duration increases to 1 hour.", heightenAt: [5] },
  { name: 'Ghostly Carrier', level: 2, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You create a Tiny, semi-corporeal figure with a form you choose. It hovers near you for the duration. When you Cast a Spell that has a range of touch, you can have the carrier move within range, deliver the spell to a creature there, and return to you. If the carrier must attempt a spell attack roll, it uses your normal bonuses. The carrier has your AC and saves, but it is destroyed by any damage.', range: '120 feet', action: '2' },
  { name: 'Humanoid Form', level: 2, tradition: 'Arcane/Occult/Primal', book: 'player-core', desc: 'You transform your appearance to that of a Small or Medium humanoid, such as a dwarf, elf, goblin, halfling, human, or orc. You gain the humanoid trait in addition to your other traits while in this form, as well as any trait related to the creature’s kind (such as goblin or human). If this transformation reduces your size, it reduces your reach accordingly (typically to 5 feet). This transformation doesn’t change your statistics in any way, and you don’t gain any special abilities of the humanoid form you assume. You can still wear and use your gear, which changes size (if necessary) to match your new form. If items leave your person, they return to their usual size. Humanoid form grants you a +4 status bonus to Deception checks to pass as a generic member of the chosen ancestry, and you add your level even if you’re untrained, but you can’t make yourself look like a specific person. If you want to Impersonate an individual, you still need to create a disguise, though the GM won’t factor in the difference in ancestry when determining the DC of your Deception check. You can Dismiss this spell.', action: '2', heightened: "(3rd) You gain darkvision or low-light vision if the form you assume has that ability. (5th) You can take on the appearance of a Large humanoid. If this increases your size, you gain the effects of the enlarge spell.", heightenAt: [3, 5] },
  { name: 'Illusory Creature', level: 2, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You create an illusory image of a Large or smaller creature. It generates the appropriate sounds, smells, and feels believable to the touch. If you and the image are ever farther than 500 feet apart, the spell ends. The image can’t speak, but you can use your actions to speak through the creature, with the spell disguising your voice as appropriate. You might need to attempt a Deception or Performance check to mimic the creature, as determined by the GM. This is especially likely if you’re trying to imitate a specific person and engage with someone that person knows. In combat, the illusion can use 2 actions per turn, which it uses when you Sustain the spell. It uses your spell attack modifier for attack rolls and your spell DC for its AC. Its saving throw modifiers are equal to your spell DC – 10. It is substantial enough that it can flank other creatures. If the image is hit by an attack or fails a save, the spell ends. The illusion can cause damage by making the target believe the illusion’s attacks are real, but it cannot otherwise directly affect the physical world. If the illusory creature hits with a Strike, the target takes 3d4 mental damage. The illusion’s Strikes are nonlethal. If the damage doesn’t correspond to the image of the monster—for example, if an illusory Large dragon deals only 5 damage—the GM might allow the target to attempt an immediate Perception check to disbelieve the spell. Any relevant resistances and weaknesses apply if the target thinks they do, as judged by the GM. For example, if the illusion wields a warhammer and attacks a creature resistant to bludgeoning damage, the creature would take less mental damage. However, illusory damage does not deactivate regeneration or trigger other effects that require a certain damage type. The GM should track illusory damage dealt by the illusion. Any creature that touches the image or uses the Seek action to examine it can attempt to disbelieve your illusion. When a creature disbelieves the illusion, it recovers from half the damage it had taken from it (if any) and doesn’t take any further damage from it.', range: '500 feet', action: '2', heightened: "(+1) The damage of the image's Strikes increases by 1d4, and the maximum size of creature you can create increases by one (to a maximum of Gargantuan).", heightenStep: 1 },
  { name: 'Invisibility', level: 2, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Illusions bend light around the target, rendering it invisible. This makes it undetected to all creatures, though the creatures can attempt to find the target, making it hidden to them instead. If the target uses a hostile action, the spell ends after that hostile action is completed. Paizo Clarification Invisibility follows the rules of the invisible condition. The second sentence summarizes them but doesn’t cover every instance, such as you being hidden to creatures observing you when you become invisible instead of being undetected to them.', range: 'touch', target: '1 creature', action: '2', heightened: "(4th) The spell lasts 1 minute, but it doesn't end if the target uses a hostile action.", heightenAt: [4] },
  { name: 'Knock', level: 2, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You make the target easier to open. Knock grants a +4 status bonus to any creature that tries to open the target door, lock, or container with an Athletics or a Thievery check. You can attempt a Thievery check to open the target as part of casting knock, and you add your level even if you’re untrained. Knock counteracts lock.', range: '30 feet', target: '1 door, lock, or container', action: '2' },
  { name: 'Laughing Fit', level: 2, tradition: 'Arcane/Occult', book: 'player-core', desc: 'The target is overtaken with uncontrollable laughter. It must attempt a Will save. Critical Success The target is unaffected. Success The target is plagued with uncontrollable laughter. It can’t use reactions. Failure The target is slowed 1 and can’t use reactions. Critical Failure The target falls prone and can’t use actions or reactions for 1 round. It then takes the effects of a failure.', range: '30 feet', target: '1 living creature', action: '2' },
  { name: 'Marvelous Mount', level: 2, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You conjure a Large fantastical creature to serve as a mount for the target. The mount is the target’s minion, has a Speed of 40 feet, and can bear the target with any carried possessions. It can’t carry any other creature. The mount uses the target’s AC and saves, but it’s destroyed if it takes more than 10 damage at one time, ending the spell.', range: '30 feet', target: 'one creature', heightened: "(3rd) The mount can walk on water, but it must end its turn on solid ground or sink. (4th) The mount has a Speed of 60 feet and can walk on water. (5th) The mount has a Speed of 60 feet and can walk on water. It also has a fly Speed of 60 feet, but it must end its turn on a surface or fall. (6th) The mount has a Speed and fly Speed of 80 feet.", heightenAt: [3, 4, 5, 6] },
  { name: 'Mist', level: 2, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You call forth a cloud of mist. All creatures within the mist become concealed, and all creatures outside the mist become concealed to creatures within it. You can Dismiss the cloud.', range: '120 feet', area: '20-foot burst', action: '3' },
  { name: 'Noise Blast', level: 2, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'A cacophonous noise blasts out, dealing 2d10 sonic damage. Each creature must attempt a Fortitude save. Critical Success The creature is unaffected. Success The creature takes half damage. Failure The creature takes full damage and is deafened for 1 round. Critical Failure The creature takes double damage and is deafened for 1 minute, and stunned 1.', damage: '2d10', range: '30 feet', area: '10-foot burst', action: '2', heightened: "(+1) The damage increases by 1d10.", heightenStep: 1, heightenDice: '1d10' },
  { name: 'Oaken Resilience', level: 2, tradition: 'Arcane/Primal', book: 'player-core', desc: 'The target’s skin becomes tough, with a consistency like bark or wood. The target gains resistance 2 to bludgeoning and piercing damage and weakness 3 to fire. After the target takes fire damage, it can Dismiss the spell as a free action triggered by taking the damage; doing so doesn’t reduce the fire damage the target was dealt.', range: 'touch', target: '1 willing creature', action: '2', heightened: "(+2) The resistances increase by 2, and the weakness increases by 3.", heightenStep: 2 },
  { name: 'One with Plants', level: 2, tradition: 'Primal', book: 'player-core', desc: 'You can either transform into a plant or merge with plant matter. While transformed, you can’t move or affect anything outside the plant, but you can cast spells as long as they don’t require line of effect beyond the plant. You can Dismiss this spell. Merge with Plants The spell’s duration is 10 minutes. While casting the spell, you must touch a plant with enough volume to fit you and your possessions or the spell is disrupted. While merged, you can hear, but not see, what’s going on outside the plant. If the plant takes damage while you’re inside it, you’re expelled from the plant and take 10d6 damage. Magic passage expels you without dealing damage. The spell ends if you’re ever outside the plant. Turn into a Plant The spell’s duration is 8 hours. You become a Large plant—typically a tree. Perception checks don’t reveal your true nature, but a successful Nature or Survival check against your spell DC reveals that you appear to be a plant that is strangely new to the area. While in this form, you can observe everything around you, using your normal senses. As a plant, your AC is 20, and only status bonuses, status penalties, circumstance bonuses, and circumstance penalties affect you. Any successes and critical successes you roll on Reflex saves are failures.', action: '2' },
  { name: 'Paranoia', level: 2, tradition: 'Occult', book: 'player-core', desc: 'You cause the target to see all other creatures as dire threats. The target is stricken by intense paranoia toward all creatures around it and must attempt a Will save. Critical Success The target is unaffected. Success The target believes everyone it sees is a potential threat. It becomes unfriendly to all creatures to which it wasn’t already hostile, even those that were previously allies. It treats no one as an ally. The spell ends after 1 round. Failure As success, but the effect lasts 1 minute. Critical Failure As failure, except the target believes that everyone it sees is a mortal enemy. It uses its reactions and free actions against everyone, regardless of whether they were previously its allies, as determined by the GM. It otherwise acts as rationally as it normally does and likely prefers to attack creatures that are actively attacking or hindering it over those leaving it alone.', range: '30 feet', target: '1 creature', action: '2', heightened: "(6th) You can target up to 5 creatures.", heightenAt: [6] },
  { name: 'Peaceful Rest', level: 2, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'The targeted corpse doesn’t decay, nor can it be transformed into an undead. If the corpse is subject to a spell that requires the corpse to have died within a certain amount of time (for example, raise dead), do not count the duration of peaceful rest against that time. This spell also prevents ordinary bugs and pests (such as maggots) from consuming the body.', range: 'touch', target: '1 corpse', action: '2', heightened: "(5th) The spell's duration is unlimited, but the spell takes one more action to cast and requires a cost (embalming fluid worth 6 gp).", heightenAt: [5] },
  { name: 'Resist Energy', level: 2, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'A shield of elemental energy protects a creature against one type of energy damage. Choose acid, cold, electricity, fire, or sonic damage. The target and its gear gain resistance 5 against the damage type you chose.', range: 'touch', target: '1 creature', action: '2', heightened: "(4th) The resistance increases to 10, and you can target up to two creatures. (7th) The resistance increases to 15, and you can target up to five creatures.", heightenAt: [4, 7] },
  { name: 'Revealing Light', level: 2, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'A wave of magical light washes over the area. You choose the appearance of the light, such as colorful, heatless flames or sparkling motes. A creature affected by revealing light is dazzled. If the creature was invisible, it becomes concealed instead. If the creature was already concealed for any other reason, it is no longer concealed. Critical Success The target is unaffected. Success The light affects the creature for 2 rounds. Failure The light affects the creature for 1 minute. Critical Failure The light affects the creature for 10 minutes.', range: '120 feet', area: '10-foot burst', action: '2' },
  { name: 'See the Unseen', level: 2, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Your gaze pierces through illusions and finds invisible creatures and spirits. You can see invisible creatures as though they weren’t invisible, although their features are blurred, making them concealed and difficult to identify. You can also see incorporeal creatures, like ghosts, phased through an object from within 10 feet of an object’s surface as blurry shapes seen through those objects. Subtler clues also grant you a +2 status bonus to checks you make to disbelieve illusions.', action: '2', heightened: "(5th) This spell has a duration of 8 hours.", heightenAt: [5] },
  { name: 'Shape Wood', level: 2, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You shape the wood into a rough shape of your choice. The shaping power is too crude to produce with intricate parts, fine details, moving pieces, or the like. You can’t use this spell to enhance the value of the wooden object you are shaping.', range: 'touch', target: 'an unworked piece of wood up to 20 cubic feet in volume', action: '2' },
  { name: 'Shatter', level: 2, tradition: 'Occult/Primal', book: 'player-core', desc: 'A high-frequency sonic attack shatters a nearby object. You deal 2d10 sonic damage to the object, ignoring the object’s Hardness if it is 4 or lower.', damage: '2d10', range: '30 feet', target: '1 unattended object', action: '2', heightened: "(+1) The damage increases by 1d10, and the Hardness the spell ignores increases by 2.", heightenStep: 1, heightenDice: '1d10' },
  { name: 'Share Life', level: 2, tradition: 'Divine', book: 'player-core', desc: 'You forge a temporary link between the target’s life essence and your own. The target takes half damage from all effects that deal Hit Point damage, and you take the remainder of the damage. When you take damage through this link, you don’t apply any resistances, weaknesses, or other abilities you have to that damage; you simply take that amount of damage. The spell ends if the target is ever more than 30 feet away from you. If either you or the target is reduced to 0 Hit Points, any damage from this spell is resolved and then the spell ends.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Shrink', level: 2, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You warp space to make a creature smaller. The target shrinks to become Tiny in size. Its equipment shrinks with it but returns to its original size if removed. The creature’s reach changes to 0 feet. This spell has no effect on a Tiny creature.', range: '30 feet', target: '1 willing creature', action: '2', heightened: "(6th) The spell can target up to 10 creatures.", heightenAt: [6] },
  { name: 'Silence', level: 2, tradition: 'Divine/Occult', book: 'player-core', desc: 'The target makes no sound, preventing creatures from noticing it using hearing alone. The target can’t use sonic attacks, nor can it use auditory actions. This also prevents the target from casting spells due to the magical words involved in casting, with the exception of subtle spells.', range: 'touch', target: '1 willing creature', action: '2', heightened: "(4th) The spell creates an aura in a 10-foot emanation around the touched creature, silencing all sound in or passing through it. While within the aura, creatures are subject to the same effects as the target. Depending upon the position of the effect, a creature might notice the lack of sound reaching it (blocking off the noise coming from a party, for example).", heightenAt: [4] },
  { name: 'Sound Body', level: 2, tradition: 'Divine/Occult/Primal', book: 'player-core', desc: 'You send a surge of healing energy to restore the target’s body. Attempt to counteract an effect of your choice imposing one of these conditions on the target: blinded, dazzled, deafened, enfeebled, or sickened. If you didn’t counteract the effect, but you would have if its counteract rank were 2 lower, instead suppress the effect until the beginning of your next turn. The effect’s duration doesn’t elapse while it’s suppressed. This spell can’t counteract or suppress curses, diseases, or conditions that are part of the target’s normal state.', range: 'touch', target: '1 willing creature', action: '2', heightened: "(4th) Add drained and slowed to the list of conditions. (6th) As 4th rank, plus add petrified. (8th) As 4th rank, plus add petrified and stunned.", heightenAt: [4, 6, 8] },
  { name: 'Speak with Animals', level: 2, tradition: 'Primal', book: 'player-core', desc: 'You can ask questions of, receive answers from, and use the Diplomacy skill with animals. The spell doesn’t make them more friendly than normal. Cunning animals are likely to be terse and evasive, while less intelligent ones often make inane comments.', action: '2' },
  { name: 'Spiritual Armament', level: 2, tradition: 'Divine/Occult', book: 'player-core', desc: 'You create a ghostly, magical echo of one weapon you’re wielding or wearing and fling it. Attempt a spell attack roll against the target’s AC, dealing 2d8 damage on a hit (or double damage on a critical hit). The damage type is the same as the chosen weapon (or any of its types for a versatile weapon). The attack deals spirit damage instead if that would be more detrimental to the creature (as determined by the GM). This attack uses and contributes to your multiple attack penalty. After the attack, the weapon returns to your side. If you sanctify the spell, the attacks are sanctified as well. Each time you Sustain the spell, you can repeat the attack against any creature within 120 feet.', damage: '2d8', range: '120 feet', target: '1 creature', action: '2', heightened: "(+2) The damage increases by 1d8.", heightenStep: 2, heightenDice: '1d8' },
  { name: 'Status', level: 2, tradition: 'Divine/Occult/Primal', book: 'player-core', desc: 'As long as you and the target are on the same plane of existence and both alive, you remain aware of its present state. You know the target’s direction from you, distance from you, and any conditions affecting it.', range: 'touch', target: '1 willing living creature', action: '2', heightened: "(4th) The spell's range increases to 30 feet, and you can target up to 10 creatures.", heightenAt: [4] },
  { name: 'Stupefy', level: 2, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You dull the target’s mind, depending on its Will save. Critical Success The target is unaffected. Success The target is stupefied 1 until the start of your next turn. Failure The target is stupefied 2 for 1 minute. Critical Failure The target is stupefied 3 for 1 minute.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Summon Elemental', level: 2, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You summon a creature that has the elemental trait and whose level is 1 or lower to fight for you.', range: '30 feet', action: '3', heightened: "(3rd) Level 2. (4th) Level 3. (5th) Level 5. (6th) Level 7. (7th) Level 9. (8th) Level 11. (9th) Level 13. (10th) Level 15.", heightenAt: [3, 4, 5, 6, 7, 8, 9, 10] },
  { name: 'Sure Footing', level: 2, tradition: 'Divine/Occult/Primal', book: 'player-core', desc: 'You free the target’s limbs from ailments that impede mobility. Attempt to counteract an effect of your choice imposing one of these conditions on the target: clumsy, grabbed, or paralyzed. If you didn’t counteract the effect, but you would have if its counteract rank were 2 lower, instead suppress the effect until the beginning of your next turn. The effect’s duration doesn’t elapse while it’s suppressed. This spell can’t counteract or suppress curses, diseases, or conditions that are part of the target’s normal state.', range: 'touch', target: '1 willing creature', action: '2', heightened: "(4th) Add immobilized, restrained, and slowed to the list of conditions. (6th) As 4th rank, plus add petrified. (8th) As 4th rank, plus add petrified and stunned.", heightenAt: [4, 6, 8] },
  { name: 'Telekinetic Maneuver', level: 2, tradition: 'Arcane/Occult', book: 'player-core', desc: 'With a rush of telekinetic power, you move a foe or something they carry. You can attempt to Disarm, Reposition, Shove, or Trip the target using a spell attack roll instead of an Athletics check.', range: '60 feet', target: '1 creature', action: '2' },
  { name: 'Translate', level: 2, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'The target can understand the meaning of a single language it is hearing or reading when you Cast the Spell. This doesn’t let it understand codes, language couched in metaphor, and the like (subject to GM discretion). If the target can hear multiple languages and knows that, it can choose which language to understand; otherwise, choose one of the languages randomly.', range: '30 feet', target: '1 creature', action: '2', heightened: "(3rd) The target can also speak the language. (4th) You can target up to 10 creatures, and targets can also speak the language.", heightenAt: [3, 4] },
  { name: 'Water Breathing', level: 2, tradition: 'Arcane/Divine/Primal', book: 'player-core', desc: 'The targets can breathe underwater.', range: '30 feet', target: 'up to 5 creatures', heightened: "(3rd) The duration is 8 hours. (4th) The duration is until your next daily preparations.", heightenAt: [3, 4] },
  { name: 'Water Walk', level: 2, tradition: 'Arcane/Divine/Primal', book: 'player-core', desc: 'The target can walk on the surface of water and other liquids without falling through. It can go underwater if it wishes, but in that case it must Swim normally. This spell doesn’t grant the ability to breathe underwater.', range: 'touch', target: '1 creature', action: '2', heightened: "(4th) The spell's range increases to 30 feet, the duration increases to 1 hour, and you can target up to 10 creatures.", heightenAt: [4] },
  // 3rd rank
  { name: 'Aqueous Orb', level: 3, tradition: 'Arcane/Primal', book: 'player-core', desc: 'A sphere of water 10 feet in diameter forms in an unoccupied space in range, either on the ground or on the surface of a liquid. When you Cast this Spell and each time you Sustain it, you can roll the orb, moving it up to 10 feet along the ground or the surface of a liquid. The orb can move through the spaces of any creatures or obstacles that wouldn’t stop the flow of water. It extinguishes non-magical fires it moves through of its size or smaller, and it attempts to counteract any magical fires it moves through. If it fails to counteract a given fire, it can’t counteract that fire for the duration of the spell. The orb can engulf Large or smaller creatures it moves through, and it can contain as many creatures as fit in its space. The orb can try to engulf the same creature only once per turn, even if you roll it onto a creature’s space more than once. Any Large or smaller creature whose space the orb tries to move through can attempt a Reflex save. Success The creature can either let the orb pass (remaining in its space or moving out of the orb’s path into a space of the creature’s choice) or allow itself to be pushed in front of the orb to the end of the orb’s movement. Failure The creature is engulfed in the orb. It moves along with the orb and must hold its breath or begin suffocating (unless it can breathe in water). An engulfed Medium or smaller creature and anyone trying to affect that creature follow the normal rules for aquatic battles. An engulfed Large creature is usually big enough that parts of it stick out from the water, and it can reach out of the water. The creature can get free either by Swimming with a successful DC 10 Athletics check or by Escaping against your spell DC. A freed creature exits the orb’s space and can immediately breathe. Critical Failure As failure, but the creature can’t Swim to get free.', range: '60 feet', action: '2' },
  { name: 'Bind Undead', level: 3, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'With a word of power, you seize control of the target. It gains the minion trait. If you or an ally uses any hostile actions against the target, the spell ends.', range: '30 feet', target: '1 mindless undead creature with a level no greater than bind undead\'s spell rank', action: '2' },
  { name: 'Blindness', level: 3, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'You blind the target. The effect is determined by the target’s Fortitude save. The target then becomes temporarily immune for 1 minute. Critical Success The target is unaffected. Success The target is blinded until its next turn begins. Failure The target is blinded for 1 minute. Critical Failure The target is blinded permanently.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Chilling Darkness', level: 3, tradition: 'Divine', book: 'player-core', desc: 'You shoot an utterly cold ray of darkness tinged with unholy energy. Make a ranged spell attack. The ray deals 5d6 cold damage. If the target has the holy trait, you deal an extra 5d6 spirit damage. Critical Success The target takes double damage. Success The target takes full damage. If the ray passes through an area of magical light or targets a creature affected by magical light, chilling darkness attempts to counteract the light. If you need to determine whether the ray passes through an area of light, draw a line between yourself and the spell’s target.', range: '120 feet', target: '1 creature', damage: '5d6', action: '2', heightened: "(+1) The cold damage increases by 2d6, and the spirit damage against holy creatures increases by 2d6.", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Clairaudience', level: 3, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You create an invisible floating ear at a location within range (even if it’s outside your line of sight or line of effect). It can’t move, but you can hear through the ear as if using your normal auditory senses.', range: '500 feet' },
  { name: 'Cozy Cabin', level: 3, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You shape a cabin 20 feet on each side and 10 feet high. This cabin has the structure trait and the same restrictions as magic items that create structures. The walls of the hut are simple and wooden, with small, square glass windows, and it has one wooden door. It doesn’t include its own lock, but it has a fastener to which a lock can be applied. The interior contains three cots, one chamber pot, and a small fireplace holding a magical fire. The interior is lit with a small magical light that you can light or extinguish at will using a Sustain action. The climate inside the hut is comfortable and allows creatures inside it to withstand most hostile weather conditions, but incredible heat or cold, powerful storms, and winds of hurricane force or greater destroy the hut. Other creatures can freely enter and exit the hut without damaging it, but if you exit the hut, the spell ends. You can Dismiss the spell.', range: '30 feet' },
  { name: 'Crisis of Faith', level: 3, tradition: 'Divine', book: 'player-core', desc: 'You assault the target’s faith, riddling the creature with doubt and mental turmoil that deal 6d6 mental damage, or 6d8 mental damage if it can cast divine spells. The effects are determined by its Will save. Critical Success The target is unaffected. Success The target takes half damage. Failure The target takes full damage; if the target can cast divine spells, it’s stupefied 1 for 1 round. Critical Failure The target takes double damage, is stupefied 1 for 1 round, and can’t cast divine spells for 1 round. To many deities, casting this spell on a follower of your own deity without significant cause is anathema.', range: '30 feet', target: '1 creature', damage: '6d6', action: '2', heightened: "(+1) The damage increases by 2d6 (or by 2d8 if the target is a divine spellcaster).", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Dream Message', level: 3, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You send a message to your target’s dream. The message is one-way, up to 1 minute of speech (roughly 150 words). If the target is asleep, they receive the message instantly. If not, they receive it the next time they sleep. As soon as they receive it, the spell ends, and you know the message was sent.', range: 'planetary', target: '1 creature you know by name and have met in person', heightened: "(4th) You can target up to 10 creatures you know by name and have met in person. You must send the same message to all of them; the spell ends for each creature individually.", heightenAt: [4] },
  { name: 'Earthbind', level: 3, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Using the weight of earth, you hamper a target’s flight, with effects based on its Fortitude save. If the creature reaches the ground safely, it doesn’t take falling damage. Critical Success The target is unaffected. Success The target falls safely up to 120 feet. Failure The target falls safely up to 120 feet. If it hits the ground, it can’t Fly, levitate, or otherwise leave the ground for 1 round. Critical Failure The target falls safely up to 120 feet. If it hits the ground, it can’t Fly, levitate, or otherwise leave the ground for 1 minute.', range: '120 feet', target: '1 flying creature', action: '2' },
  { name: 'Enthrall', level: 3, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Your words fascinate your targets. You speak or sing without interruption throughout the casting and duration. Targets who notice your speech or song might give their undivided attention; each target must attempt a Will save. The GM might grant a circumstance bonus (to a maximum of +4) if the target is of an opposing religion, ancestry, or political leaning, or is otherwise unlikely to agree with what you’re saying. Each creature that comes within range has to attempt a save when you Sustain the spell. If you’re speaking, enthrall gains the linguistic trait. Critical Success The target is unaffected and notices that you tried to use magic. Success The target needn’t pay attention but doesn’t notice you tried to use magic (it might notice others are enthralled). Failure The target is fascinated with you. It can attempt another Will save if it witnesses actions or speech with which it disagrees. If it succeeds, it’s no longer fascinated and is temporarily immune for 1 hour. If the target is subject to a hostile act, or if another creature succeeds at a Diplomacy or Intimidation check against it, the fascination ends immediately. Critical Failure As failure, but the target can’t attempt a save to end the fascination if it disagrees with you.', range: '120 feet', target: 'all creatures in range', action: '2' },
  { name: 'Feet to Fins', level: 3, tradition: 'Arcane/Primal', book: 'player-core', desc: 'The target’s feet transform into fins, improving mobility in the water but reducing it on land. The target gains a swim Speed equal to its normal land Speed, but its land Speed becomes 5 feet.', range: 'touch', target: '1 willing creature', action: '2', heightened: "(6th) The spell lasts until your next daily preparations.", heightenAt: [6] },
  { name: 'Fireball', level: 3, tradition: 'Arcane/Primal', book: 'player-core', desc: 'A roaring blast of fire detonates at a spot you designate, dealing 6d6 fire damage.', range: '500 feet', area: '20-foot burst', damage: '6d6', action: '2', heightened: "(+1) The damage increases by 2d6.", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Ghostly Weapon', level: 3, tradition: 'Arcane/Occult', book: 'player-core', desc: 'The target weapon becomes translucent and ghostly, and it can affect material and incorporeal creatures and objects. It gains the effects of the ghost touch property rune, meaning it is magical if it wasn’t already, is especially effective against incorporeal creatures, and can be wielded by a corporeal or incorporeal creature.', range: 'touch', target: '1 weapon that is either unattended or wielded by you or a willing ally', action: '2' },
  { name: 'Haste', level: 3, tradition: 'Arcane/Occult/Primal', book: 'player-core', desc: 'Magic empowers the target to act faster. It gains the quickened condition and can use the extra action each round for only Strike and Stride actions.', range: '30 feet', target: '1 creature', action: '2', heightened: "(7th) You can target up to 6 creatures.", heightenAt: [7] },
  { name: 'Heroism', level: 3, tradition: 'Divine/Occult', book: 'player-core', desc: 'You unlock the target’s inner heroism, granting it a +1 status bonus to attack rolls, Perception checks, saving throws, and skill checks.', range: 'touch', target: '1 creature', action: '2', heightened: "(6th) The status bonus increases to +2. (9th) The status bonus increases to +3.", heightenAt: [6, 9] },
  { name: 'Holy Light', level: 3, tradition: 'Divine/Primal', book: 'player-core', desc: 'You shine a blazing ray of light tinged with holy energy. Make a ranged spell attack. The ray deals 5d6 fire damage. If the target has the unholy trait, you deal an extra 5d6 spirit damage. Critical Success The target takes double damage. Success The target takes full damage. If the light passes through an area of magical darkness or targets a creature affected by magical darkness, holy light attempts to counteract the darkness. If you need to determine whether the light passes through an area of darkness, draw a line between yourself and the spell’s target.', range: '120 feet', target: '1 creature', damage: '5d6', action: '2', heightened: "(+1) The fire damage increases by 2d6, and the spirit damage against unholy creatures increases by 2d6.", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Hypercognition', level: 3, tradition: 'Occult', book: 'player-core', desc: 'You rapidly catalog and collate information relevant to your current situation. You can instantly use up to 6 Recall Knowledge actions as part of Casting this Spell. For these actions, you can’t use any special abilities, reactions, or free actions that trigger when you Recall Knowledge.', action: '1' },
  { name: 'Hypnotize', level: 3, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You create a cloud of mesmerizing patterns and colors that hovers in the air. Creatures are dazzled while inside the cloud. In addition, a creature must attempt a Will saving throw if it is inside the cloud when you cast it, when it enters the cloud, when it ends its turn within the cloud, or if it uses a Seek or Interact action on the cloud. A creature currently fascinated by hypnotize doesn’t attempt new saves. Success The target is unaffected. Failure The target is fascinated by the cloud. Critical Failure The target is fascinated by the cloud. While it remains fascinated, it can’t use reactions.', range: '120 feet', area: '10-foot burst', action: '2' },
  { name: 'Insect Form', level: 3, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You envision a simple bug and transform into a Medium animal battle form. When you Cast this Spell, choose a listed battle form. You can decide the specific type of animal (such as such as a ladybug or scarab for beetle), but this has no effect on the form’s Size or statistics. While in this form, you gain the animal trait. You can Dismiss this spell. You gain the following statistics and abilities regardless of which battle form you choose: AC = 18 + your level. Ignore your armor’s check penalty and Speed reduction. 10 temporary Hit Points. Low-light vision. One or more attacks specific to the battle form you choose, which are the only attacks you can Strike with. You’re trained with them. Your attack modifier is +13, and your damage bonus is +2. These attacks are Strength based (for the purpose of the enfeebled condition). If your unarmed attack modifier is higher, you can use it instead. Athletics modifier of +13, unless your own is higher. You gain specific abilities based on the form you choose: Ant Speed 30 feet, climb 30 feet; Melee 1 Action mandibles, Damage 2d6 bludgeoning. Beetle Speed 25 feet; Melee 1 Action mandibles, Damage 2d10 bludgeoning. Centipede Speed 25 feet, climb 25 feet; darkvision; Melee 1 Action mandibles, Damage 1d8 piercing plus 1d4 persistent poison. Mantis Speed 40 feet; imprecise scent 30 feet; Melee 1 Action foreleg, Damage 2d8 piercing. Scorpion Speed 40 feet; darkvision, imprecise tremorsense 60 feet; Melee 1 Action stinger, Damage 1d8 piercing plus 1d4 persistent poison; Melee 1 Action pincer (agile), Damage 1d6 bludgeoning. Spider Speed 25 feet, climb 25 feet; darkvision; Melee 1 Action fangs, Damage 1d6 piercing plus 1d4 persistent poison; Ranged 1 Action web (range increment 20 feet), Damage immobilizes the target for 1 round or until it Escapes.', action: '2', heightened: "(4th) Your battle form is Large, and your attacks have 10-foot reach. You instead gain 15 temporary HP, attack modifier +16, damage bonus +6, and Athletics +16. (5th) Your battle form is Huge, and your attacks have 15-foot reach. You instead gain 20 temporary HP, attack modifier +18, damage bonus +2 and double damage dice (including persistent damage), and Athletics +20.", heightenAt: [4, 5] },
  { name: 'Levitate', level: 3, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You defy gravity and levitate the target 5 feet off the ground. You can Sustain the spell to move the target up or down 10 feet. A creature floating in the air from levitate takes a –2 circumstance penalty to attack rolls. A floating creature can spend an Interact action to stabilize itself and negate this penalty for the remainder of its turn. If the target is adjacent to a fixed object or terrain of suitable stability, it can move across the surface by climbing (if the surface is vertical, like a wall) or crawling (if the surface is horizontal, such as a ceiling). The GM determines which surfaces can be climbed or crawled across.', range: 'touch', target: '1 unattended object or willing creature', action: '2' },
  { name: 'Lightning Bolt', level: 3, tradition: 'Arcane/Primal', book: 'player-core', desc: 'A bolt of lightning strikes outward from your hand, dealing 4d12 electricity damage with a basic Reflex save.', area: '120-foot line', damage: '4d12', action: '2', heightened: "(+1) The damage increases by 1d12.", heightenStep: 1, heightenDice: '1d12' },
  { name: 'Locate', level: 3, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You learn the direction to the target (if you picked a specific object, such as “my mother’s sword”) or the nearest target (if you picked a type of object, such as “swords”). If the target is a specific object, you must have observed it directly with your own senses. If it’s a type of object, you still need to have an accurate mental image of the type of object. If there’s lead or running water between you and the target, this spell can’t locate the object. This means you might find a type of object farther away if the nearest one is behind lead or running water.', range: '500 feet', target: '1 specific object or type of object', heightened: "(5th) You can target a specific creature or ancestry instead of an object, but you must have met or seen up close the creature or ancestry you want to target.", heightenAt: [5] },
  { name: 'Mad Monkeys', level: 3, tradition: 'Primal', book: 'player-core', desc: 'Magical monkey spirits fill the area as they pile and climb on top of one another. Because the monkeys are magical spirits, they can’t be attacked or hurt. Casting calm or a similar effect over the monkeys makes them docile, causing them to cease making mischief for the duration of mad monkeys. Choose the kind of mischief your monkeys make when you Cast the Spell. They produce the effect listed for that mischief when you Cast the Spell and the first time each round when you Sustain the spell. The first time each round when you Sustain the spell, you can move the area of the monkeys by 5 feet. Flagrant Burglary The monkeys try to Steal any one item from one creature in the area. Use your spell DC – 10 as the monkeys’ Thievery modifier. Their attempt relies more on distraction than subtlety, so the victim knows what item the monkeys were trying to take and whether it was taken. Getting a stolen item from the monkeys— even for the caster—requires Stealing it from them or Disarming them, using your spell DC. When the spell ends, any stolen items fall to the ground in any square of the spell’s area you choose. Raucous Din The monkeys screech loudly, potentially deafening creatures in the spell’s area. Each creature in the spell’s area must attempt a Fortitude save. Critical Success The creature is unaffected and is temporarily immune for 10 minutes. Success The creature is unaffected. Failure The creature is deafened for 1 round. Critical Failure The creature is deafened for 1 minute. Tumultuous Gymnastics The monkeys jump and climb all over creatures in the spell’s area, interfering with complex movements. Each creature in the spell’s area must attempt a Reflex save. Critical Success The creature is unaffected and is temporarily immune for 10 minutes. Success The creature is unaffected. Failure For 1 round, the creature must succeed at a DC 5 flat check whenever it attempts a manipulate action. If it fails this check, the action is disrupted. Critical Failure As failure, but the monkeys cling to the creature tenaciously, and the effect lasts until the spell ends, even if the creature leaves the spell’s area.', range: '30 feet', area: '5-foot burst', action: '2' },
  { name: 'Mind Reading', level: 3, tradition: 'Arcane/Occult', book: 'player-core', desc: 'With a cursory mental touch, you attempt to read the target’s mind. It must attempt a Will save. The target then becomes temporarily immune to your mind reading for 1 hour. Critical Success The target perceives vague surface thoughts from you when you Cast the Spell. Success You find out whether the target’s Intelligence modifier is higher than, equal to, or lower than yours. Failure You perceive vague surface thoughts from the target when you Cast the Spell, and you find out whether its Intelligence is higher than, equal to, or lower than yours. Critical Failure As failure, and for the duration of the spell, you can Sustain the spell to detect the target’s surface thoughts again. The target doesn’t receive any additional saves.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'One with Stone', level: 3, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You can either transform into a stone or merge with stone. This spell has the same effects as one with plants, but lets you merge with or turn into stone. A stone you turn into has AC 23. You can Dismiss this spell.', action: '2' },
  { name: 'Paralyze', level: 3, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You block the target’s motor impulses before they can leave its mind, freezing target in place. The target must attempt a Will save. Critical Success The target is unaffected. Success The target is stunned 1. Failure The target is paralyzed for 1 round. Critical Failure The target is paralyzed for 4 rounds. At the end of each of its turns, it can attempt a new Will save to reduce the remaining duration by 1 round, or end it entirely on a critical success.', range: '30 feet', target: '1 creature', action: '2', heightened: "(7th) You can target up to 10 creatures.", heightenAt: [7] },
  { name: 'Ring of Truth', level: 3, tradition: 'Divine/Occult', book: 'player-core', desc: 'You designate an area in which lies are revealed. Creatures in the area also take a –2 status penalty to Deception checks. Each time a creature in the area speaks a true statement, the soft ring of a bell sounds in the area. Creatures are aware of the magic; therefore, they can avoid answering questions to which they would normally respond with a lie, or they can be evasive as long as they remain within the boundaries of the truth. If a creature is in the area when the spell is cast or later enters the area, that creature attempts a Will save. It uses the results of this initial save if it leaves and reenters the area. Critical Success The target is so convincing that the bell rings even if they lie. Success If the target lies and succeeds at their Deception check against all targets, the bell still rings. Failure The bell accurately sees through their deception and will never ring if they lie.', range: '30 feet', area: '20-foot burst', action: '2' },
  { name: 'Safe Passage', level: 3, tradition: 'Arcane/Divine/Primal', book: 'player-core', desc: 'You make passage through the area safe for a brief amount of time. Anyone passing through the area gains the following benefits against harmful effects of the terrain and environment, including environmental damage, hazardous terrain, and hazards in the area. The spell grants a +2 status bonus to AC and saves against such effects, and resistance 5 to all damage from such effects. Furthermore, the spell prevents anything in the area that’s prone to collapse, such as a rickety bridge or an unstable ceiling, from collapsing, except under extreme strain that would collapse a normal structure of its type. Safe passage protects only against harm, not inconvenience, and it doesn’t reduce difficult terrain, remove the concealed condition caused by precipitation, or the like, nor does it protect against creatures within the spell’s area.', range: 'touch', area: '10-foot-wide, 10-foot-tall, 60-foot-long section of terrain', action: '3', heightened: "(5th) The granted resistance increases to 10, and the area can be 120 feet long. (8th) The granted resistance increases to 15, and the area can be 500 feet long.", heightenAt: [5, 8] },
  { name: 'Slow', level: 3, tradition: 'Arcane/Occult/Primal', book: 'player-core', desc: 'You dilate the flow of time around the target, slowing its actions. Critical Success The target is unaffected. Success The target is slowed 1 for 1 round. Failure The target is slowed 1 for 1 minute. Critical Failure The target is slowed 2 for 1 minute.', range: '30 feet', target: '1 creature', action: '2', heightened: "(6th) You can target up to 10 creatures.", heightenAt: [6] },
  { name: 'Speak with Plants', level: 3, tradition: 'Divine/Occult/Primal', book: 'player-core', desc: 'You can ask questions of and receive answers from plants and fungi, but the spell doesn’t make them more friendly or intelligent than normal. Most normal plants and fungi have a distinctive view of the world around them, so they don’t recognize details about creatures or know anything about the world beyond their immediate vicinity. Cunning plant or fungus monsters are likely to be terse and evasive, while less intelligent ones often make inane comments.', action: '2', heightened: "(4th) The duration is 8 hours.", heightenAt: [4] },
  { name: 'Vampiric Feast', level: 3, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Your touch leeches the lifeblood out of a target to empower yourself. You deal 6d6 void damage to the target. You gain temporary Hit Points equal to half the void damage the target takes (after applying resistances and the like). You lose any remaining temporary Hit Points after 1 minute.', range: 'touch', target: '1 living creature', damage: '6d6', action: '2', heightened: "(+1) The damage increases by 2d6.", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Veil of Privacy', level: 3, tradition: 'Arcane/Occult/Primal', book: 'player-core', desc: 'You erect protective wards that make the target difficult to detect via magic. Veil of privacy attempts to counteract all detection, revelation, and scrying effects used against the target or the target’s gear throughout the duration, counting cantrips as 1st-rank spells for this purpose. Successfully counteracting a spell that targets an area or multiple targets negates the effects for only veil of privacy’s target.', range: 'touch', target: '1 creature or object' },
  { name: 'Wall of Thorns', level: 3, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You grow a wall of thorny brambles from the ground. You create a 5-foot-thick wall of brambles and thorns in a straight line up to 60 feet long and 10 feet high. You must create the wall in an unbroken open space so its edges don’t pass through any creatures or objects, or the spell is lost. The wall stands vertically. If you wish, the wall can be of a shorter length or height. Everything on each side of the wall has cover from creatures on the opposite side, and the wall’s spaces are difficult terrain. For every move action a creature uses to enter at least one of the wall’s spaces, that creature takes 3d4 piercing damage. Each 10-foot-by-10-foot section of the wall has AC 10, Hardness 10, and 20 Hit Points. It’s immune to critical hits and precision damage. A destroyed section can be moved through freely.', range: '60 feet', damage: '3d4', action: '3', heightened: "(+1) The Hit Points of each section of the wall increase by 5, and the piercing damage increases by 1d4.", heightenStep: 1, heightenDice: '1d4' },
  { name: 'Wall of Wind', level: 3, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You create a barrier of gusting winds that hinders anything moving through it. The wall of swirling winds is 5 feet thick, 60 feet long, and 30 feet high. The wall stands vertically, but you can shape its path. Though the wall of wind distorts the air, it does not hamper sight. The wall has the following effects. Ammunition from physical ranged attacks—such as arrows, bolts, sling bullets, and other objects of similar size—can’t pass through the wall. Attacks with bigger ranged weapons, such as javelins, take a –2 circumstance penalty to their attack rolls if their paths pass through the wall. Massive ranged weapons and spell effects that don’t create physical objects pass through the wall with no penalty. The wall is difficult terrain to creatures attempting to move overland through it. Gases, including creatures in vapor form, can’t pass through the wall. A creature that attempts to fly through the wall using a move action must attempt a Fortitude save. Critical Success The creature can move through the wall normally this turn. Success The flying creature can move through the wall this turn, but the wall is difficult terrain. Failure The wall stops the movement of the flying creature, and any remaining movement from its current action is wasted. Critical Failure As failure, and the creature is pushed 10 feet away from the wall.', range: '120 feet', action: '3' },
  // 4th rank
  { name: 'Aerial Form', level: 4, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You harness your mastery of the sky to reshape your body into a Medium flying animal battle form. When you Cast this Spell, choose a listed battle form. You can decide the specific type of animal (such as an owl or eagle for bird), but this has no effect on the form’s Size or statistics. While in this form, you gain the animal trait. You can Dismiss the spell. You gain specific abilities based on the animal you choose: AC = 18 + your level. Ignore your armor’s check penalty and Speed reduction. 5 temporary Hit Points. Low-light vision. One or more unarmed melee attacks specific to the battle form you choose, which are the only attacks you can Strike with. You’re trained with them. Your attack modifier is +16, and your damage bonus is +5. These attacks are Dexterity based (for the purpose of the clumsy condition, for example). If your attack modifier for Dexterity-based unarmed attacks is higher, you can use it instead. Acrobatics modifier of +16, unless your own is higher. You also gain specific abilities based on the form you choose: Bat Speed 20 feet, fly 30 feet; precise echolocation 40 feet; Melee 1 Action fangs, Damage 2d8 piercing; Melee 1 Action wing (agile), Damage 2d6 bludgeoning. Bird Speed 10 feet, fly 50 feet; Melee 1 Action beak, Damage 2d8 piercing; Melee 1 Action talon (agile), Damage 1d10 slashing. Pterosaur Speed 10 feet, fly 40 feet; imprecise scent 30 feet; Melee 1 Action beak, Damage 3d6 piercing. Wasp Speed 20 feet, fly 40 feet; Melee 1 Action stinger, Damage 1d8 piercing plus 1d6 persistent poison.', duration: '1 minute', action: '2' },
  { name: 'Clairvoyance', level: 4, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You create an invisible floating eye at a location within range (even if it’s outside your line of sight or line of effect). The eye can’t move, but you can see in all directions from that point as if using your normal visual senses.', range: '500 feet', duration: '10 minutes' },
  { name: 'Confusion', level: 4, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You befuddle your target with strange impulses, causing it to act randomly. The effects are determined by the target’s Will save. You can Dismiss the spell. Critical Success The target is unaffected. Success The target babbles incoherently and is stunned 1. Failure The target is confused for 1 minute. It can attempt a new save at the end of each of its turns to end the confusion. Critical Failure The target is confused for 1 minute, with no save to end early.', range: '30 feet', target: '1 creature', duration: '1 minute', action: '2', heightened: "(8th) You can target up to 10 creatures.", heightenAt: [8] },
  { name: 'Creation', level: 4, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You conjure a temporary object from magical energy. It must consist of earthen or plant-derived matter (such as wood, paper, brick, or stone) and be 5 cubic feet or smaller. It can’t rely on intricate artistry or complex moving parts, never fulfills a cost or the like, and can’t be made of precious materials or materials with a rarity of uncommon or higher. It is obviously temporarily conjured, and thus can’t be sold or passed off as a genuine item. The spell gains the appropriate trait for the item created, typically earth, plant, or wood.', range: '0 feet', duration: '1 hour', heightened: "(5th) The item is metal and can include common minerals, like feldspar or quartz. The spell gains the metal trait if used to create a metal object.", heightenAt: [5] },
  { name: 'Detect Scrying', level: 4, tradition: 'Arcane/Occult', book: 'player-core', desc: 'By reading trace auras, you detect the presence of scrying effects in the area. If detect scrying is higher rank than a scrying effect, you gain a glimpse of the scrying creature and learn its approximate distance and direction.', area: '30-foot emanation', duration: '1 hour', action: '2', heightened: "(6th) The duration is until your next daily preparations.", heightenAt: [6] },
  { name: 'Dinosaur Form', level: 4, tradition: 'Primal', book: 'player-core', desc: 'You channel the primal forces of nature to transform into a Large animal battle form, specifically that of a powerful and terrifying dinosaur. When you Cast this Spell, choose a listed battle form. You can decide the specific type of animal, but this has no effect on the form’s Size or statistics. While in this form, you gain the animal and dinosaur traits. You can Dismiss the spell. You gain the following statistics and abilities regardless of which battle form you choose: AC = 18 + your level. Ignore your armor’s check penalty and Speed reduction. 15 temporary Hit Points. Low-light vision and imprecise scent 30 feet. One or more unarmed melee attacks specific to the battle form you choose, which are the only attacks you can Strike with. You’re trained with them. Your attack modifier is +16, and your damage bonus is +9. These attacks are Strength based (for the purpose of the enfeebled condition, for example). If your unarmed attack modifier is higher, you can use it instead. Athletics modifier of +18, unless your own is higher. You also gain specific abilities based on the form you choose: Ankylosaurus Speed 25 feet; Melee 1 Action tail (backswing, reach 10 feet), Damage 2d6 bludgeoning; Melee 1 Action foot, Damage 2d6 bludgeoning. Brontosaurus Speed 25 feet; Melee 1 Action tail (reach 15 feet), Damage 2d6 bludgeoning; Melee 1 Action foot, Damage 2d8 bludgeoning. Deinonychus Speed 40 feet; Melee 1 Action talon (agile), Damage 2d4 piercing plus 1 persistent bleed; Melee 1 Action jaws, Damage 1d10 piercing. Stegosaurus Speed 30 feet; Melee 1 Action tail (reach 10 feet), Damage 2d8 piercing. Triceratops Speed 30 feet; Melee 1 Action horn, Damage 2d8 piercing, plus 1d6 persistent bleed on a critical hit; Melee 1 Action foot, Damage 2d6 bludgeoning. Tyrannosaurus Speed 30 feet; Melee 1 Action jaws (deadly d12, reach 10 feet), Damage 1d12 piercing; Melee 1 Action tail (reach 10 feet), Damage 1d10 bludgeoning.', duration: '1 minute', action: '2' },
  { name: 'Dispelling Globe', level: 4, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You create an immobile globe around yourself. It attempts to counteract any spell from outside the globe whose area or targets enter into it, as if the globe were a dispel magic spell 1 rank lower than its actual spell rank. If the counteract attempt succeeds, it prevents only the portion of the spell that would have entered the globe (so if the spell also has targets outside the globe, or part of its area is beyond the globe, those targets or that area are affected normally). You must form the sphere in an unbroken open space, so its edges don’t pass through any creatures or objects, or the spell is lost (though creatures can enter the globe after the spell is cast).', area: '10-foot burst', duration: '10 minutes', action: '2' },
  { name: 'Divine Wrath', level: 4, tradition: 'Divine', book: 'player-core', desc: 'You channel the fury of divinity against your foes. You deal 4d10 spirit damage to enemies in the area, depending on their Fortitude save. Critical Success The creature is unaffected. Success The creature takes half damage. Failure The creature takes full damage and is sickened 1. Critical Failure The creature takes full damage and is sickened 2; while it’s sickened, it’s also slowed 1.', range: '120 feet', area: '20-foot burst', damage: '4d10', action: '2', heightened: "(+1) The damage increases by 1d10.", heightenStep: 1, heightenDice: '1d10' },
  { name: 'Fire Shield', level: 4, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You create a hovering shield made of fire. As long as the shield persists, its heat grants you cold resistance 5 and makes you immune to mild and severe environmental cold. You can Raise a Shield with the fire shield as a normal shield to gain a +1 circumstance bonus to AC. You can use the Shield Block reaction with the fire shield, which has Hardness 10, is immune to fire, and has 40 HP (with no Broken Threshold), and its Hardness is halved against effects that have the water trait. If you Shield Block a melee attack that is either an unarmed attack or made by an adjacent attacker, the attacker takes 2d6 fire damage.', duration: '1 minute', damage: '2d6', action: '2', heightened: "(+2) The cold resistance increases by 5, the HP increase by 10, and the fire damage increases by 1d6.", heightenStep: 2, heightenDice: '1d6' },
  { name: 'Flicker', level: 4, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You flicker quickly between your current plane and another. You gain resistance 5 to all damage, except force. At the end of each of your turns, you automatically teleport 10 feet in a random direction, as determined by the GM. You can Sustain the spell to teleport in this way.', duration: '1 minute', action: '2', heightened: "(+2) The resistance increases by 3.", heightenStep: 2 },
  { name: 'Fly', level: 4, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'The target can soar through the air, gaining a fly Speed equal to its Speed or 20 feet, whichever is greater.', range: 'touch', target: '1 creature', duration: '5 minutes', action: '2', heightened: "(7th) The duration increases to 1 hour.", heightenAt: [7] },
  { name: 'Honeyed Words', level: 4, tradition: 'Occult', book: 'player-core', desc: 'Falsehoods pass your lips as smoothly as silk. You gain a +4 status bonus to Deception checks to Lie and against Perception checks to discern if you are telling the truth, and you add your level even if untrained. If the implausibility of your lies prompts a circumstance penalty or a DC increase, reduce that penalty by half or increase it by half.', duration: '10 minutes', action: '2' },
  { name: 'Hydraulic Torrent', level: 4, tradition: 'Primal', book: 'player-core', desc: 'A swirling torrent of water manifests along a straight line, battering creatures and unattended objects in its path and possibly pushing them away from you. The torrent deals 8d6 bludgeoning damage. Each creature in the area must attempt a basic Fortitude save; unattended objects automatically fail. Creatures and objects that fail are also knocked back 5 feet (10 feet on a critical failure).', area: '60-foot line', damage: '8d6', action: '2', heightened: "(+1) The damage increases by 2d6.", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Liminal Doorway', level: 4, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You draw a chalk doorway on an unbroken surface, which opens into an extradimensional space. Any creature treating the drawing as an actual door can Interact to touch the doorknob and pass through. The warped, chalk-drawn room beyond the door is 20 feet in width, depth, and height. The space is unadorned and empty, with chalk lines indicating the corners of the walls. If the drawing is scrubbed away, the underlying surface is broken, or a creature attempts to enter the space that would put it over capacity, the space begins to collapse. The space ejects one creature at random each round, depositing it on the nearest open ground, until all creatures are returned outside.', range: 'touch', duration: '8 hours' },
  { name: 'Mirage', level: 4, tradition: 'Arcane/Occult/Primal', book: 'player-core', desc: 'You create an illusion that causes natural terrain to look, sound, feel, and smell like a different kind of terrain. This doesn’t disguise any structures or creatures in the area. Any creature that touches the illusion or uses the Seek action to examine it can attempt to disbelieve your illusion.', range: '500 feet', area: '50-foot burst', duration: 'until your next daily preparations', heightened: "(5th) Your image can also disguise structures or create illusory structures (but still doesn't disguise creatures).", heightenAt: [5] },
  { name: 'Mountain Resilience', level: 4, tradition: 'Arcane/Primal', book: 'player-core', desc: 'The target’s skin hardens like the stone of a mountain face. It gains resistance 5 to physical damage, except adamantine. Each time the target is hit by a bludgeoning, piercing, or slashing attack, mountain resilience’s duration decreases by 1 minute.', range: 'touch', target: '1 creature', duration: '20 minutes', action: '2', heightened: "(6th) The resistance increases to 10. (8th) The resistance increases to 15. (10th) The resistance increases to 20.", heightenAt: [6, 8, 10] },
  { name: 'Nightmare', level: 4, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You send disturbing nightmares to your target. The next time the target falls asleep, it must attempt a Will save. If you know the target only by name and have never met them, the target gets a +4 circumstance bonus to the Will save. Critical Success The target is unaffected and is temporarily immune for 1 week. Success The target has the nightmares but has no adverse effects other than unpleasant memories. Failure The target has the nightmares and awakens fatigued. Critical Failure The target has the nightmares, awakens fatigued, and is drained 2 until it is no longer fatigued.', range: 'planetary', target: '1 creature you know by name', duration: '1 day' },
  { name: 'Outcast’s Curse', level: 4, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You afflict the target with a curse that makes its presence abrasive and off-putting. The target must attempt a Will save. Critical Success The target is unaffected. Success For 10 minutes, the target must roll twice and use the worse result whenever attempting a Deception, Diplomacy, Intimidation, or Performance check, and creatures they encounter have an initial attitude toward them of one step worse (for instance, unfriendly instead of indifferent). Failure As success, but the effect is permanent. Critical Failure As failure, and creatures that the target encounters have an initial attitude toward them of two steps worse.', range: 'touch', target: '1 creature', action: '2' },
  { name: 'Peaceful Bubble', level: 4, tradition: 'Arcane/Occult', book: 'player-core', desc: 'An opaque shell of drifting, iridescent runes covers the area, creating a bubble. You can choose to make the burst smaller, in 10-foot increments. The runes don’t block travel, but those inside the bubble can’t perceive those outside it and vice versa. Detection and scrying effects are likewise blocked. Creatures sleeping within the bubble are immune to dreams sent by spells. Those sleeping 8 hours reduce their doomed condition by 2 instead of 1.', range: 'touch', area: '100-foot burst', duration: '24 hours' },
  { name: 'Planar Tether', level: 4, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'You stitch the target to its current plane. While the target is affected by planar tether, the spell attempts to counteract any teleportation effect that would move the target, or any effect that would transport it to a different plane. Planar tether’s duration is determined by the target’s Will save. Critical Success The target is unaffected. Success The duration is 1 minute. Failure The duration is 10 minutes. Critical Failure The duration is 1 hour.', range: '30 feet', target: '1 creature', duration: 'varies', action: '2' },
  { name: 'Read Omens', level: 4, tradition: 'Divine/Occult', book: 'player-core', desc: 'You peek into the future. Choose a particular goal or activity you plan to engage in within 1 week, or an event you expect might happen within 1 week. You learn a cryptic clue or piece of advice that could help with the chosen event, often in the form of a rhyme or omen.' },
  { name: 'Rewrite Memory', level: 4, tradition: 'Occult', book: 'player-core', desc: 'You alter the target’s memories by erasing a memory, enhancing a memory’s clarity, altering a memory, or adding a false memory. The target can attempt a Will save to resist the spell. Critical Success The target is unaffected and realizes you tried to alter its memory. Success The target is unaffected but thinks your spell was something harmless instead of rewrite memory, unless it identifies the spell. Failure During the first 5 minutes of the spell’s duration, you can Sustain the spell to modify a memory once each round. When you do, you imagine up to 6 seconds of memory to modify, to a maximum of 5 continuous minutes of memory. Any memories you’ve altered remain changed as long as the spell is active. If the target moves out of range before the 5 minutes is up, you can’t alter any further memories.', range: '30 feet', target: '1 creature', duration: 'unlimited', action: '2', heightened: "(6th) You can Cast the Spell on a willing target to suppress all memory of a particular topic, detailed in 50 words or fewer. The effect is permanent, and it patches these omissions with an indistinct haze.", heightenAt: [6] },
  { name: 'Shape Stone', level: 4, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You shape the stone into a rough shape of your choice. The shaping process is too crude to produce intricate parts, fine details, moving pieces, or the like. Any creatures standing atop the stone when you reshape it must each attempt a Reflex save or Acrobatics check. Success The creature is unaffected. Failure The creature falls prone atop the stone. Critical Failure The creature falls off the stone (if applicable) and lands prone.', range: 'touch', target: 'cube of stone 10 feet across or smaller', action: '2' },
  { name: 'Suggestion', level: 4, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Your honeyed words are difficult for creatures to resist. You suggest a course of action to the target, which must be phrased in such a way as to seem like a logical course of action to the target and can’t be self-destructive or obviously against the target’s self-interest. The target must attempt a Will save. Critical Success The target is unaffected and knows you tried to control it using a spell. Success The target is unaffected. Failure The target immediately follows your suggestion. The spell has a duration of 1 minute, or until the target has completed a finite suggestion or the suggestion becomes self-destructive or has other obvious negative effects. Critical Failure As failure, but the base duration is 1 hour.', range: '30 feet', target: '1 creature', duration: 'varies', action: '2', heightened: "(8th) You can target up to 10 creatures.", heightenAt: [8] },
  { name: 'Talking Corpse', level: 4, tradition: 'Divine/Occult', book: 'player-core', desc: 'You grant the target corpse a semblance of life, which it uses to speak the answers to three questions posed to it. This spell calls on the physical body’s latent memories rather than summoning back the deceased’s spirit, so the corpse must be mostly intact for the spell to function. The more damage the corpse has taken, the more inaccurate or patchwork its answers are, and it must have a throat and mouth to speak at all. If anyone has previously cast this spell on the corpse in the last week, the spell automatically fails. The corpse can attempt a Will save to resist answering the questions using the statistics of the original creature at its time of death, with the following effects. Critical Success The target can lie or refuse to answer, and the target’s spirit haunts you for 24 hours, bothering you and causing you to be unable to gain any rest for that time. Success The target can provide false information or refuse to answer your questions. Failure The target must answer truthfully, but its answers can be brief, cryptic, and repetitive. It can still mislead you or attempt to stall so that the spell’s duration runs out before you can ask all your questions. Critical Failure As failure, but the target’s answers are more direct and less repetitive, though still cryptic. It takes a –2 status penalty to Deception checks to deceive or mislead you.', range: 'touch', target: '1 corpse', duration: '10 minutes' },
  { name: 'Telepathy', level: 4, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You can communicate telepathically with creatures within 30 feet. Once you establish a connection by communicating with a creature, the communication is two-way. You can communicate with only creatures that share a language with you.', duration: '10 minutes', action: '2', heightened: "(6th) You can communicate telepathically with creatures using shared mental imagery even if you don't share a language; telepathy loses the linguistic trait.", heightenAt: [6] },
  { name: 'Translocate', level: 4, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You instantly transport yourself and any items you’re wearing and holding from your current space to an unoccupied space within range you can see. If this would bring another creature with you—even if you’re carrying it in an extradimensional container—the spell is lost.', range: '120 feet', action: '2', heightened: "(5th) The range increases to 1 mile. You don't need to be able to see your destination, as long as you have been there in the past and know its relative location and distance from you. You are then temporarily immune for 1 hour.", heightenAt: [5] },
  { name: 'Unfettered Movement', level: 4, tradition: 'Arcane/Divine/Primal', book: 'player-core', desc: 'You repel hindrances that would affect a creature. While under this spell’s effect, the target ignores effects that would give them a circumstance penalty to Speed. When they attempt to Escape an effect that has them immobilized, grabbed, or restrained, they automatically succeed unless the effect is magical and of a higher rank than the unfettered movement spell.', range: 'touch', target: '1 creature touched', duration: '10 minutes', action: '2' },
  { name: 'Vapor Form', level: 4, tradition: 'Arcane/Occult/Primal', book: 'player-core', desc: 'The target transforms into a vaporous state. In this state, the target is amorphous. It loses any item bonus to AC and all other effects and bonuses from armor, and it uses its proficiency modifier for unarmored defense. It gains resistance 8 to physical damage and is immune to precision damage. It can’t cast spells, activate items, or use actions that have the attack or manipulate trait. It gains a fly Speed of 10 feet and can slip through tiny cracks. The target can Dismiss the spell.', range: 'touch', target: '1 willing creature', duration: '5 minutes', action: '2' },
  { name: 'Vision of Death', level: 4, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You force the target to see a vision of its own death. It takes 8d6 mental damage with a Will save. If the target is reduced to 0 HP by this spell, its vision becomes reality and kills it instantly. Critical Success The target is unaffected. Success The target takes half damage and is frightened 1. Failure The target takes full damage and is frightened 2. Critical Failure The target takes double damage, is frightened 4, and is fleeing for as long as it’s frightened.', range: '120 feet', target: '1 living creature', damage: '8d6', action: '2', heightened: "(+1) The damage increases by 2d6.", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Vital Beacon', level: 4, tradition: 'Divine/Primal', book: 'player-core', desc: 'Vitality radiates outward from you, allowing others to supplicate and receive healing. Once per round, either you or an ally can use an Interact action to supplicate and lay hands upon you to regain Hit Points. Each time the beacon heals someone, it decreases in strength. It restores 4d10 Hit Points to the first creature, 4d8 Hit Points to the second, 4d6 Hit Points to the third, and 4d4 Hit Points to the fourth, after which the spell ends. You can have only one vital beacon active at a time.', duration: 'until your next daily preparations', heightened: "(+1) The beacon restores one additional die of HP each time it heals, using the normal die size for that step.", heightenStep: 1 },
  { name: 'Wall of Fire', level: 4, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You raise a blazing wall that burns creatures passing through it. You create either a 5-foot-thick wall of flame in a straight line up to 60 feet long and 10 feet high, or a 5-foot-thick, 10-foot-radius ring of flame with the same height. The wall stands vertically in either form; if you wish, the wall can be of a shorter length or height. Everything on each side of the wall is concealed from creatures on the opposite side. Any creature that crosses the wall or is occupying the wall’s area at the start of its turn takes 4d6 fire damage.', range: '120 feet', duration: '1 minute', damage: '4d6', action: '3', heightened: "(+1) The fire damage increases by 1d6.", heightenStep: 1, heightenDice: '1d6' },
  { name: 'Weapon Storm', level: 4, tradition: 'Arcane/Primal', book: 'player-core', desc: 'You swing a weapon you’re holding, and the weapon magically multiplies into duplicates that swipe at all creatures in either a cone or an emanation. This flurry deals four dice of damage to creatures in the area. This damage has the same type as the weapon and uses the same die size. Determine the die size as if you were attacking with the weapon; for instance, if you were wielding a two-hand weapon in both hands, you’d use its two-hand damage die. Critical Success The creature is unaffected. Success The target takes half damage. Failure The target takes full damage. Critical Failure The target takes double damage and is subject to the weapon’s critical specialization effect.', area: '30-foot cone or 10-foot emanation', action: '2', heightened: "(+1) Add another damage die.", heightenStep: 1 },
  // 5th rank
  { name: 'Banishment', level: 5, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'Send a creature back to its home plane.', range: '30 feet', target: '1 creature that isn\'t on its home plane', action: '2', heightened: "(9th) You can target up to 10 creatures. The extra cost affects targets to which it is anathema.", heightenAt: [9] },
  { name: 'Breath of Life', level: 5, tradition: 'Divine', book: 'player-core', desc: 'React to revive a character at the moment of its death.', range: '60 feet', target: 'the triggering creature', damage: '5d8', action: 'R', heightened: "(+2) The healing increases by 1d8.", heightenStep: 2, heightenDice: '1d8' },
  { name: 'Control Water', level: 5, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Raise or lower water in a large area.', range: '500 feet', area: '50 feet long by 50 feet wide', duration: '1 hour', action: '2' },
  { name: 'Divine Immolation', level: 5, tradition: 'Divine', book: 'player-core', desc: 'Call divine fire from the sky.', range: '120 feet', area: '20-foot burst', damage: '6d6', action: '2', heightened: "(+1) The damage increases by 1d6 and persistent damage increases by 1d6.", heightenStep: 1, heightenDice: '1d6' },
  { name: 'Dreaming Potential', level: 5, tradition: 'Occult', book: 'player-core', desc: 'The target retrains in its dreams.', range: 'touch', target: '1 willing sleeping creature', duration: '8 hours' },
  { name: 'Elemental Form', level: 5, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Turn into an elemental.', duration: '1 minute', action: '2' },
  { name: 'False Vision', level: 5, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Trick a scrying spell.', range: 'touch', area: '100-foot burst', duration: 'until your next daily preparations' },
  { name: 'Hallucination', level: 5, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Cause a creature to believe one thing is another, to notice something that isn’t there, or to be unable to detect something.', range: '30 feet', target: '1 creature', duration: '1 hour', action: '2', heightened: "(6th) Choose to either target up to 10 creatures or change the spell's duration to until your next daily preparations. (8th) Choose to either target any number of creatures or change the spell's duration to unlimited.", heightenAt: [6, 8] },
  { name: 'Howling Blizzard', level: 5, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Fill a cone or burst with cold winds and snowdrifts.', area: '60-foot cone', damage: '10d6', action: '2', heightened: "(+1) The damage increases by 2d6.", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Illusory Scene', level: 5, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Create an imaginary scene containing multiple creatures and objects.', range: '500 feet', area: '30-foot burst', duration: '1 hour', heightened: "(6th) Creatures or objects in your scene can speak. You must speak the specific lines for each actor when creating your program. The spell disguises your voice for each actor. (8th) As the 6th-rank version, and the duration is unlimited.", heightenAt: [6, 8] },
  { name: 'Impaling Spike', level: 5, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Skewer a creature with a cold iron spike.', range: '30 feet', target: '1 creature', duration: '1 minute', damage: '8d6', action: '2', heightened: "(+1) The damage increases by 2d6.", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Invoke Spirits', level: 5, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Call a group of ghostly apparitions to attack your foes.', range: '120 feet', area: '10-foot burst', duration: 'sustained up to 1 minute', damage: '2d4', action: '2', heightened: "(+2) The mental damage and void damage each increase by 1d4.", heightenStep: 2, heightenDice: '1d4' },
  { name: 'Magic Passage', level: 5, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Open a temporary passage through a surface.', range: 'touch', area: '5-foot-wide, 10-foot-tall, 10-foot-deep section of wooden, plaster, or stone wall', duration: '1 hour', action: '2', heightened: "(7th) The tunnel can be up to 20 feet deep. The areas of the wall that contain your tunnel's entrance appear completely normal (unless viewed with truesight or a similar effect), despite the tunnel's existence. The tunnel's entrance functions as a solid wall, but you can specify a password or a trigger, allowing creatures to enter freely.", heightenAt: [7] },
  { name: 'Mariner’s Curse', level: 5, tradition: 'Arcane/Occult/Primal', book: 'player-core', desc: 'Infect a creature with the curse of the rolling sea.', range: 'touch', target: '1 creature', action: '2' },
  { name: 'Mind Probe', level: 5, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Uncover knowledge and memories in a creature’s mind.', range: '30 feet', target: '1 creature', duration: 'sustained up to 1 minute' },
  { name: 'Moon Frenzy', level: 5, tradition: 'Primal', book: 'player-core', desc: 'Give willing creatures fangs and claws, and send them into a frenzy.', range: '30 feet', target: 'up to 5 willing creatures', duration: '1 minute', action: '2', heightened: "(6th) The temporary Hit Points increase to 10, the silver weakness to 10, and the damage dealt by the attacks to three dice. (10th) The temporary Hit Points increase to 20, the silver weakness to 20, and the damage dealt by the attacks to four dice.", heightenAt: [6, 10] },
  { name: 'Nature’s Pathway', level: 5, tradition: 'Primal', book: 'player-core', desc: 'Teleport from tree to tree.', heightened: "(6th) The tree you exit can be up to 50 miles away. (8th) The tree you exit can be up to 500 miles away. (9th) The tree you exit can be anywhere on the same planet.", heightenAt: [6, 8, 9] },
  { name: 'Plant Form', level: 5, tradition: 'Primal', book: 'player-core', desc: 'Turn into a dangerous plant creature.', duration: '1 minute', action: '2' },
  { name: 'Scouting Eye', level: 5, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Invisible eye transmits what it sees to you.', range: 'see text', duration: 'sustained' },
  { name: 'Sending', level: 5, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Send a message to a creature anywhere on the planet and get a reply.', range: 'planetary', target: '1 creature you know well', action: '3' },
  { name: 'Shadow Blast', level: 5, tradition: 'Divine/Occult', book: 'player-core', desc: 'Shape a damaging cone of shadow substance to deal damage of a type you choose.', range: 'varies', area: 'varies', damage: '6d8', action: '2', heightened: "(+1) The damage increases by 1d8.", heightenStep: 1, heightenDice: '1d8' },
  { name: 'Slither', level: 5, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Shadowy snakes bite and capture creatures.', range: '120 feet', area: '20-foot burst', duration: '1 minute', damage: '3d6', action: '3', heightened: "(+2) The persistent poison damage increases by 1d6 and snake HP increases by 6.", heightenStep: 2 },
  { name: 'Speak with Stones', level: 5, tradition: 'Divine/Occult/Primal', book: 'player-core', desc: 'Communicate with natural and worked stone.', duration: '1 hour', action: '2', heightened: "(6th) The duration is 8 hours.", heightenAt: [6] },
  { name: 'Spiritual Guardian', level: 5, tradition: 'Divine', book: 'player-core', desc: 'Create a magical guardian to attack at your command and take damage for your allies.', range: '120 feet', duration: 'sustained up to 1 minute', damage: '3d8', action: '2', heightened: "(+2) The guardian's damage increases by 1d8, and its Hit Points increase by 20.", heightenStep: 2, heightenDice: '1d8' },
  { name: 'Subconscious Suggestion', level: 5, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Plant a suggestion in a creature’s mind that it must follow when a trigger occurs.', range: '30 feet', target: '1 creature', duration: 'varies', action: '2', heightened: "(9th) You can target up to 10 creatures.", heightenAt: [9] },
  { name: 'Summon Celestial', level: 5, tradition: 'Divine', book: 'player-core', desc: 'Conjure a celestial to fight for you.', range: '30 feet', duration: 'sustained up to 1 minute', action: '3', heightened: "(6th) Level 7. (7th) Level 9. (8th) Level 11. (9th) Level 13. (10th) Level 15.", heightenAt: [6, 7, 8, 9, 10] },
  { name: 'Summon Dragon', level: 5, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'Conjure a dragon to fight on your behalf.', range: '30 feet', duration: 'sustained up to 1 minute', action: '3', heightened: "(6th) Level 7. (7th) Level 9. (8th) Level 11. (9th) Level 13. (10th) Level 15.", heightenAt: [6, 7, 8, 9, 10] },
  { name: 'Summon Entity', level: 5, tradition: 'Occult', book: 'player-core', desc: 'Conjure an aberration to fight on your behalf.', range: '30 feet', duration: 'sustained up to 1 minute', action: '3', heightened: "(6th) Level 7. (7th) Level 9. (8th) Level 11. (9th) Level 13. (10th) Level 15.", heightenAt: [6, 7, 8, 9, 10] },
  { name: 'Summon Fiend', level: 5, tradition: 'Divine', book: 'player-core', desc: 'Conjure a fiend to fight on your behalf.', range: '30 feet', duration: 'sustained up to 1 minute', action: '3', heightened: "(6th) Level 7. (7th) Level 9. (8th) Level 11. (9th) Level 13. (10th) Level 15.", heightenAt: [6, 7, 8, 9, 10] },
  { name: 'Summon Giant', level: 5, tradition: 'Primal', book: 'player-core', desc: 'Conjure a giant to fight on your behalf.', range: '30 feet', duration: 'sustained up to 1 minute', action: '3', heightened: "(6th) Level 7. (7th) Level 9. (8th) Level 11. (9th) Level 13. (10th) Level 15.", heightenAt: [6, 7, 8, 9, 10] },
  { name: 'Summon Monitor', level: 5, tradition: 'Divine', book: 'player-core', desc: 'Conjure a planar monitor to fight on your behalf.', range: '30 feet', duration: 'sustained up to 1 minute', action: '3', heightened: "(6th) Level 7. (7th) Level 9. (8th) Level 11. (9th) Level 13. (10th) Level 15.", heightenAt: [6, 7, 8, 9, 10] },
  { name: 'Synaptic Pulse', level: 5, tradition: 'Occult', book: 'player-core', desc: 'Slow creatures with a mental blast.', area: '30-foot emanation', duration: '1 round', action: '2' },
  { name: 'Telekinetic Haul', level: 5, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Move a large object.', range: '120 feet', target: '1 unattended object of up to 80 Bulk with no dimension longer than 20 feet', duration: 'sustained up to 1 minute', action: '2' },
  { name: 'Toxic Cloud', level: 5, tradition: 'Arcane/Primal', book: 'player-core', desc: 'A bank of poison fog rolls away from you.', range: '120 feet', area: '20-foot burst', duration: '1 minute', damage: '6d8', action: '3', heightened: "(+1) The damage increases by 1d8.", heightenStep: 1, heightenDice: '1d8' },
  { name: 'Truespeech', level: 5, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Let a creature understand and speak all languages.', range: 'touch', target: '1 creature', duration: '1 hour', action: '2', heightened: "(7th) The duration is 8 hours.", heightenAt: [7] },
  { name: 'Umbral Journey', level: 5, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Travel rapidly via the Netherworld.', range: 'touch', target: 'you and up to 10 willing creatures touched', duration: '8 hours' },
  { name: 'Wall of Ice', level: 5, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Sculpt a foot-thick wall of ice that blocks sight and can chill creatures.', range: '120 feet', duration: '1 minute', damage: '2d6', action: '3', heightened: "(+2) The Hit Points of each section of the wall increase by 10, and the cold damage dealt to creatures crossing a destroyed section increases by 1d6.", heightenStep: 2, heightenDice: '1d6' },
  { name: 'Wall of Stone', level: 5, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Shape a wall of stone.', range: '120 feet', action: '3', heightened: "(+2) The Hit Points of each section of the wall increase by 15.", heightenStep: 2 },
  { name: 'Wave of Despair', level: 5, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Drive creatures in an area to despair.', area: '30-foot cone', duration: '1 or more rounds', action: '2', heightened: "(7th) The area increases to a 60-foot cone.", heightenAt: [7] },
  // 6th rank
  { name: 'Blessed Boundary', level: 6, tradition: 'Divine', book: 'player-core', desc: 'Manifest divine force in a protective sphere.', range: '120 feet', area: '60-foot burst', action: '3' },
  { name: 'Chain Lightning', level: 6, tradition: 'Arcane/Primal', book: 'player-core', desc: 'An arc of lightning jumps from creature to creature.', range: '500 feet', target: '1 creature, plus any number of additional creatures', action: '2' },
  { name: 'Cursed Metamorphosis', level: 6, tradition: 'Arcane/Occult/Primal', book: 'player-core', desc: 'Transform the target into a harmless animal.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Disintegrate', level: 6, tradition: 'Arcane', book: 'player-core', desc: 'Reduce a creature or object to dust.', range: '120 feet', target: '1 creature, unattended object, or force construct', action: '2' },
  { name: 'Dominate', level: 6, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'A creature must obey your orders.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Dragon Form', level: 6, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'Turn into a dragon.', action: '2' },
  { name: 'Field of Life', level: 6, tradition: 'Divine/Primal', book: 'player-core', desc: 'Create a vital energy field that heals those who remain within.', range: '30 feet', area: '20-foot burst', action: '2' },
  { name: 'Mislead', level: 6, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Turn invisible and create a duplicate of yourself who acts like you.', action: '2' },
  { name: 'Never Mind', level: 6, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Stupefy a creature permanently.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Petrify', level: 6, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Turn a creature into a stone statue.', range: '120 feet', target: '1 creature made of organic material', action: '2' },
  { name: 'Phantasmal Calamity', level: 6, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Create visions of an apocalypse to damage creatures mentally.', range: '500 feet', area: '30-foot burst', action: '2' },
  { name: 'Raise Dead', level: 6, tradition: 'Divine', book: 'player-core', desc: 'Return a dead creature to life.', range: '10 feet', target: '1 dead creature of 13th level or lower' },
  { name: 'Repulsion', level: 6, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Prevent creatures from approaching you.', range: 'emanation up to 40-feet', action: '2' },
  { name: 'Scrying', level: 6, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Spy on a creature you choose.', range: 'planetary', target: '1 creature' },
  { name: 'Spellwrack', level: 6, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Curse a creature to be harmed when a spell is cast on it and lower the duration of its spells.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Spirit Blast', level: 6, tradition: 'Divine/Occult', book: 'player-core', desc: 'Damage a creature’s spiritual essence.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Tangling Creepers', level: 6, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Entangle creatures in a burst and concentrate to lash out with immobilizing vines.', range: '500 feet', area: '40-foot burst', action: '3' },
  { name: 'Teleport', level: 6, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Transport you and willing creatures a great distance.', range: '100 miles', target: 'you and up to 4 targets touched, either willing creatures or objects roughly the size of a creature.' },
  { name: 'Tree of Seasons', level: 6, tradition: 'Primal', book: 'player-core', desc: 'Grow a tree with four explosive seedpods.', range: '60 feet', action: '2' },
  { name: 'Truesight', level: 6, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'See through illusions and physical transformations.', action: '2' },
  { name: 'Vampiric Exsanguination', level: 6, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Draw blood and life force from creatures in a cone, harming them and healing yourself.', area: '30-foot cone', action: '2' },
  { name: 'Vibrant Pattern', level: 6, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Make a pattern of lights that dazzles and blinds creatures who enter the area.', range: '120 feet', area: '10-foot burst', action: '2' },
  { name: 'Wall of Force', level: 6, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Create an invisible and durable plane of magical force.', range: '30 feet', action: '3' },
  { name: 'Zealous Conviction', level: 6, tradition: 'Divine/Occult', book: 'player-core', desc: 'Instill unshakable conviction and zeal in willing creatures.', range: '30 feet', target: 'up to 10 willing creatures', action: '2' },
  // 7th rank
  { name: 'Contingency', level: 7, tradition: 'Arcane', book: 'player-core', desc: 'Set up a spell to trigger later under your choice of circumstances.' },
  { name: 'Divine Decree', level: 7, tradition: 'Divine', book: 'player-core', desc: 'Creatures opposing your deity’s will are damaged, enfeebled, or banished.', area: '40-foot emanation', action: '2' },
  { name: 'Duplicate Foe', level: 7, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Create a temporary duplicate of an enemy to fight for you.', range: '30 feet', target: '1 enemy of level 15 or lower', action: '3' },
  { name: 'Eclipse Burst', level: 7, tradition: 'Arcane/Divine/Primal', book: 'player-core', desc: 'Explode a globe of darkness that deals cold damage, hurts the living, and overcomes light.', range: '500 feet', area: '60-foot burst', action: '2' },
  { name: 'Energy Aegis', level: 7, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'A creature gains resistance to acid, cold, electricity, fire, force, sonic, vitality and void damage.', range: 'touch', target: '1 creature' },
  { name: 'Execute', level: 7, tradition: 'Divine/Primal', book: 'player-core', desc: 'Pull a living creature toward death or an undead creature toward destruction.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Fiery Body', level: 7, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Turn your body into living flame.', action: '2' },
  { name: 'Interplanar Teleport', level: 7, tradition: 'Arcane/Divine/Occult/Primal', book: 'player-core', desc: 'Transport creatures to another plane in the Multiverse.', range: '5 feet', target: 'up to 8 willing creatures' },
  { name: 'Mask of Terror', level: 7, tradition: 'Arcane/Occult/Primal', book: 'player-core', desc: 'Create a fearsome illusory appearance that frightens observers.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Planar Palace', level: 7, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Conjure a secure dwelling in a demiplane.', range: '30 feet' },
  { name: 'Planar Seal', level: 7, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Raise a barrier against teleportation and summoning.', range: '120 feet', area: '60-foot burst', action: '2' },
  { name: 'Possession', level: 7, tradition: 'Occult', book: 'player-core', desc: 'Send your mind and soul into another creature’s body.', range: '30 feet', target: '1 living creature', action: '2' },
  { name: 'Project Image', level: 7, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Make an illusion of yourself you can cast spells through.', range: '30 feet', action: '2' },
  { name: 'Regenerate', level: 7, tradition: 'Divine/Primal', book: 'player-core', desc: 'Creature heals over time, regrows organs, and reattaches body parts.', range: 'touch', target: '1 willing living creature', action: '2' },
  { name: 'Retrocognition', level: 7, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Sense impressions of past events at your location.' },
  { name: 'Sunburst', level: 7, tradition: 'Divine/Primal', book: 'player-core', desc: 'A globe of sunlight deals fire damage, hurts undead, and overcomes darkness.', range: '500 feet', area: '60-foot burst', action: '2' },
  { name: 'True Target', level: 7, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Make multiple attacks against a creature especially accurate.', range: '60 feet', target: '4 creatures', action: '1' },
  { name: 'Unfettered Pack', level: 7, tradition: 'Primal', book: 'player-core', desc: 'Let creatures avoid environmental hindrances.', range: '30 feet', target: 'up to 10 creatures', action: '2' },
  { name: 'Volcanic Eruption', level: 7, tradition: 'Primal', book: 'player-core', desc: 'Cause massive lava sprays that burn creatures and encase them in rock.', range: '120 feet', area: '5-foot cylinder', action: '2' },
  { name: 'Warp Mind', level: 7, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Confuse a creature, possibly permanently.', range: '120 feet', target: '1 creature', action: '2' },
  // 8th rank
  { name: 'Arctic Rift', level: 8, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Bitter cold damages and freezes a creature.', area: '120-foot line', action: '2' },
  { name: 'Canticle of Everlasting Grief', level: 8, tradition: 'Divine/Occult', book: 'player-core', desc: 'Sing a mournful dirge that frightens and mentally damages a foe, preventing its bonuses.', range: '120 feet', target: '1 creature', action: '2' },
  { name: 'Desiccate', level: 8, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Pull moisture from creatures, damaging them.', range: '500 feet', target: 'any number of living creatures', action: '2' },
  { name: 'Disappearance', level: 8, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Make a creature invisible, silent, and undetectable by special senses.', range: 'touch', target: '1 creature', action: '2' },
  { name: 'Divine Inspiration', level: 8, tradition: 'Divine', book: 'player-core', desc: 'Spiritual energy recovers a creature’s expended spell.', range: 'touch', target: '1 willing creature', action: '2' },
  { name: 'Earthquake', level: 8, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Shake the ground with a devastating earthquake.', range: '500 feet', area: '60-foot burst', action: '2' },
  { name: 'Hidden Mind', level: 8, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Protect a creature from mental magic and effects that pry into its secrets.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Migration', level: 8, tradition: 'Primal', book: 'player-core', desc: 'Turn creatures into swift-moving animals.', range: '20 feet', target: 'you and up to 5 willing creatures' },
  { name: 'Moment of Renewal', level: 8, tradition: 'Divine/Primal', book: 'player-core', desc: 'Give a creature a day’s worth of recovery in an instant.', range: 'touch', target: 'up to 6 creatures', action: '2' },
  { name: 'Monstrosity Form', level: 8, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Turn into a powerful monster.', action: '2' },
  { name: 'Pinpoint', level: 8, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Learn the exact location of a creature or object.', range: 'unlimited', target: '1 creature or object' },
  { name: 'Punishing Winds', level: 8, tradition: 'Primal', book: 'player-core', desc: 'A cyclone inhibits flight and traps creatures.', range: '100 feet', area: '30-foot cylinder', action: '3' },
  { name: 'Quandary', level: 8, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Trap a creature in an extradimensional puzzle.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Uncontrollable Dance', level: 8, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Overcome a target with an all-consuming urge to dance.', range: 'touch', target: '1 creature', action: '2' },
  { name: 'Unrelenting Observation', level: 8, tradition: 'Arcane/Occult', book: 'player-core', desc: 'You and other creatures track a subject exactly using scrying.', range: '100 feet', target: '1 creature or object tracked and up to 5 other willing creatures', area: '20-foot burst', action: '2' },
  { name: 'Detonate Magic', level: 9, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Counteract a magic item or spell, causing a damaging explosion.', damage: '8d6', range: '120 feet', target: '1 magic item or spell effect', area: '5-foot emanation', action: '2' },
  { name: 'Falling Stars', level: 9, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Call down an array of falling stars that explode into airbursts, asteroids, comets, or plasma.', damage: '6d10', range: '500 feet', action: '2' },
  { name: 'Foresight', level: 9, tradition: 'Arcane/Divine/Occult', book: 'player-core', desc: 'Grant a sixth sense that warns the target of danger, giving a bonus to initiative and letting it reroll a triggered save.', range: 'touch', target: '1 creature', action: '2' },
  { name: 'Massacre', level: 9, tradition: 'Arcane/Divine/Primal', book: 'player-core', desc: 'Unleash a wave of death along a line, dealing void damage and instantly slaying weakened creatures.', damage: '9d6', area: '60-foot line', action: '2' },
  { name: 'Metamorphosis', level: 9, tradition: 'Arcane/Primal', book: 'player-core', desc: 'Transform into any form you could take with a polymorph spell you know or could prepare of 8th rank or lower.', action: '2' },
  { name: 'Phantasmagoria', level: 9, tradition: 'Arcane/Occult', book: 'player-core', desc: 'Fill targets\' minds with endless images, dealing mental damage and potentially leaving them confused.', damage: '16d6', range: '120 feet', target: 'any number of creatures', action: '2' },
  // Focus Spells
  { name: 'Agile Feet', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'The blessings of your god make your feet faster and your movements more fluid.', duration: 'until the end of the current turn', action: '1' },
  { name: 'Allegro', level: 7, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You perform rapidly, speeding up your ally. The ally becomes quickened and can use the additional action to Strike, Stride, or Step.', range: '30 feet', target: '1 ally', action: '1' },
  { name: 'Animal Feature', level: 2, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'Without fully transforming your body, you gain one animalistic feature, which you select from the list below each time you Cast the Spell.', action: '1' },
  { name: 'Appearance of Wealth', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You create a brief vision of immense wealth filling the spell\'s area.', range: '30 feet', area: '5-foot burst', duration: 'sustained up to 1 minute', action: '2' },
  { name: 'Artistic Flourish', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You transform the target into a form that more closes matches your creative vision.', range: '15 feet', target: '1 item or work of art that fits entirely within the range', action: '2' },
  { name: 'Athletic Rush', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your body fills with physical power and skill.', duration: '1 round', action: '1' },
  { name: 'Bit of Luck', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You tilt the scales of luck slightly to protect a creature from disaster.', range: '30 feet', target: '1 willing creature', duration: '1 minute', action: '2' },
  { name: 'Blood Ward', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron\'s aegis descends to shield a target from harm.', range: '30 feet', target: '1 creature', duration: 'sustained up to 1 minute', action: '1', heightened: "(5th) The status bonus increases to +2.", heightenAt: [5] },
  { name: 'Cackle', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'With a quick burst of laughter, you prolong a magical effect you created.', action: 'F' },
  { name: 'Captivating Adoration', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You become intensely entrancing, and creatures are distracted by you as long as they remain within the area.', area: '15-foot emanation', action: '2' },
  { name: 'Charming Push', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You push at the target\'s mind to deflect their ire.', range: '30 feet', target: '1 creature', duration: 'until the start of your next turn', action: '1' },
  { name: 'Charming Touch', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You infuse your target with attraction, causing it to act friendlier toward you.', range: 'touch', target: '1 creature that could find you attractive', duration: '10 minutes', action: '1' },
  { name: 'Clinging Ice', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Freezing sleet and heavy snowfall collect on the target’s feet and legs, dealing 1d4 cold damage and other effects depending on its Reflex save. Critical Success The target is unaffected. Success The target takes half damage. Failure The target takes full damage and a –5-foot circumstance penalty to its Speeds until the spell ends. Critical Failure The target takes double damage and a –10-foot circumstance penalty to its Speeds until the spell ends.', damage: '1d4', range: '30 feet', target: '1 creature', action: '1', heightened: "(+1) The damage increases by 1d4.", heightenStep: 1, heightenDice: '1d4' },
  { name: 'Cloak of Shadow', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You drape the target in a mantle of swirling shadows that make it harder to see.', range: 'touch', target: '1 willing creature', duration: '1 minute', action: '1' },
  { name: 'Commanding Lash', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'With the threat of more pain, you compel a creature you\'ve recently harmed.', range: '100 feet', target: 'A creature you dealt damage to on your most recent action.', action: '1' },
  { name: 'Community Restoration', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'When you use your magic to support your allies, shared strength bolsters you all.', action: 'R' },
  { name: 'Competitive Edge', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your competitiveness drives you to prove yourself against the opposition.', action: '1' },
  { name: 'Cornucopia', level: 1, focus: true, tradition: 'Druid', book: 'player-core', desc: 'Vines twine into a wicker horn in your hands, and out spills a single fruit, nut, or similar small bit of produce.', duration: '10 minutes', damage: '1d6+4', action: '2', heightened: "(+1) The cornucopia produces an additional piece of food. A creature can consume any amount of food from the same casting with a single Interact action. Eating six pieces of produce from the cornucopia gives as much nourishment as one square meal for a typical human.", heightenStep: 1 },
  { name: 'Counter Performance', level: 1, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your performance protects you and your allies.', area: '60-foot emanation', action: 'R' },
  { name: 'Courageous Anthem', level: 1, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You inspire yourself and your allies with words or tunes of encouragement. You and all allies in the area gain a +1 status bonus to attack rolls, damage rolls, and saves against fear effects.', area: '60-foot emanation', action: '1' },
  { name: 'Creative Splash', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'A deluge of paint or colorful illusions descend on the area, reflecting your personal creative specialty.', range: '30 feet', area: '5-foot burst', duration: 'varies', action: '2' },
  { name: 'Cry of Destruction', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your voice booms, smashing what\'s in front of you.', damage: '1d8', area: '15-foot cone', action: '2', heightened: "(+1) The damage increases by 1d8.", heightenStep: 1, heightenDice: '1d8' },
  { name: 'Curse of Death', level: 5, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron wraps a hand around your target\'s heart.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Darkened Sight', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You infuse a creature\'s vision with darkness.', range: '60 feet', target: '1 creature', action: '2' },
  { name: 'Dazzling Flash', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You raise your religious symbol and create a blinding flash of light.', area: '15-foot cone', action: '2', heightened: "(3rd) The area increases to a 30-foot cone.", heightenAt: [3] },
  { name: 'Death\'s Call', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Seeing another pass from this world invigorates you.', duration: '1 minute', action: 'R' },
  { name: 'Deceiver\'s Cloak', level: 3, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron drapes a cloak of illusion about you, making you appear as another creature of the same body shape with roughly similar height and weight as yourself.', action: '2' },
  { name: 'Delusional Pride', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You make the target overconfident, leading it to ascribe failure to external factors.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Destructive Aura', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Swirling sands of divine devastation surround you, weakening the defenses of all they touch.', area: '15-foot emanation', action: '2' },
  { name: 'Dirge of Doom', level: 3, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Enemies within the area are frightened 1. They can’t reduce their frightened value below 1 while they remain in the area.', area: '30-foot emanation', action: '1' },
  { name: 'Discern Secrets', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron deigns to whisper a few secrets. The target can Recall Knowledge, Seek, or Sense Motive as a free action. The target gains a +1 status bonus to the statistic used for the roll (a skill or Perception) on the roll and as long as you Sustain the spell. The target is temporarily immune to discern secrets for 1 minute.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Disperse into Air', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'After taking the triggering damage, you transform into air.', action: 'R' },
  { name: 'Downpour', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You call forth a torrential downpour, which extinguishes non-magical flames.', range: '120 feet', area: '30-foot burst', action: '2' },
  { name: 'Dreamer\'s Call', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You create a vivid, illusory daydream drawn from the images of the target\'s dreams.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Earthworks', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'With a ripple of earth, you raise small barriers from the ground.', range: '60 feet', area: '5-foot burst or more', duration: '1 minute', action: '1-3', heightened: "(4th) You pull the barriers to float in the air, causing the spell to function as difficult terrain for flying creatures.", heightenAt: [4] },
  { name: 'Elemental Betrayal', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron uses its superior command of the elements, empowering them to undermine your foe.', range: '30 feet', target: '1 creature', duration: 'sustained up to 1 minute', action: '1', heightened: "(+2) Increase the weakness by 1.", heightenStep: 2 },
  { name: 'Enduring Might', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your own might mingles with divine power to protect you from harm.', action: 'R' },
  { name: 'Energy Absorption', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You\'re used to mitigating the damage done by bombs, siege engines, and magical artillery.', action: 'R' },
  { name: 'Enlarge Companion', level: 2, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'Your animal companion grows much larger, towering over its foes in battle.', range: '30 feet', target: 'your animal companion', action: '2' },
  { name: 'Ephemeral Tracking', level: 3, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You can look at currents in the air and water and see tracks that you can follow just as you would on land.', action: '2' },
  { name: 'Eradicate Undeath', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'A massive deluge of life energy causes the undead to fall apart.', damage: '4d12', area: '30-foot cone', action: '2', heightened: "(+1) The damage increases by 1d12.", heightenStep: 1, heightenDice: '1d12' },
  { name: 'Evil Eye', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron’s resentment manifests in a baleful, envious gaze. The target becomes sickened 1 if it fails a Will save (or sickened 2 on a critical failure). This condition value can’t be reduced below 1 while the spell is active and you can see the target.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Face in the Crowd', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'While in a crowd of roughly similar creatures, your appearance becomes bland and nondescript.', duration: '1 minute', action: '1', heightened: "(3rd) The spell gains a range of 10 feet and can target up to 10 creatures.", heightenAt: [3] },
  { name: 'Fatal Aria', level: 10, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You perform music so perfect that the target may die of joy or sorrow.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Fire Ray', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'A blazing band of fire arcs through the air, lighting your opponent and the ground they stand upon on fire. Make a spell attack roll against the target’s AC. The ray deals 2d6 fire damage on a hit (or double damage on a critical hit). On any result other than a critical failure, the ground in the target’s space catches fire, dealing 1d6 fire damage to each creature that ends its turn in one of the squares.', damage: '2d6', range: '60 feet', target: '1 creature', duration: 'until the end of the target\'s next turn', action: '2', heightened: '(+1) The ray’s initial damage increases by 2d6, and the fire damage dealt by the burning space increases by 1d6.', heightenStep: 1, heightenDice: '2d6' },
  { name: 'Flame Barrier', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You swiftly deflect incoming flames.', range: '30 feet', target: 'the creature that would take fire damage', action: 'R' },
  { name: 'Force Bolt', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You fire an arrow-shaped bolt of force, one of the most common and reliable forms of battle magic. It automatically hits and deals 1d4+1 force damage to the target.', damage: '1d4+1', range: '30 feet', target: '1 creature', action: '1', heightened: "(+2) The damage increases by 1d4+1.", heightenStep: 2, heightenDice: '1d4+1' },
  { name: 'Fortify Summoning', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'As you call a creature to your side, your magic transforms its body, heightening its ferocity and fortifying its resilience.', range: '30 feet', target: '1 creature you summoned', action: '1' },
  { name: 'Fortissimo Composition', level: 4, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You call upon your muse to greatly increase the benefits you provide with your courageous anthem , rallying anthem , or song of strength composition.', action: 'F' },
  { name: 'Glimpse the Truth', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Divine insight lets you see things as they are, unveiled by attempts to magically cloak the truth.', area: '30-foot emanation', action: '1' },
  { name: 'Gravity Weapon', level: 1, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You build up gravitational force and funnel it into your blows, leading to more powerful attacks with blade and bow alike.', duration: '1 minute', action: '1' },
  { name: 'Hand of the Apprentice', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You take advantage of one of the most fundamental lessons of magic to levitate and propel your weapon.', range: '500 feet', target: '1 creature', action: '1' },
  { name: 'Heal Animal', level: 1, focus: true, tradition: 'Druid', book: 'player-core', desc: 'You heal an animal\'s wounds, restoring 1d8 Hit Points to the target.', range: 'varies', target: '1 willing living animal', damage: '1d8', action: '1-2', heightened: "(+1) The amount of healing increases by 1d8, and the additional healing for the 2-action version increases by 8.", heightenStep: 1, heightenDice: '1d8' },
  { name: 'Heal Companion', level: 1, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You heal your animal companion\'s wounds.', range: 'touch or 30 feet', target: 'your animal companion', damage: '1d10', action: '1-2', heightened: "(+1) The amount of healing increases by 1d10, and the additional healing for the 2-action version increases by 8.", heightenStep: 1, heightenDice: '1d10' },
  { name: 'Healer\'s Blessing', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your words bless a creature with an enhanced connection to vital energy.', range: '30 feet', target: '1 willing living creature', duration: '1 minute', action: '1', heightened: "(+1) The additional healing increases by 2 HP.", heightenStep: 1 },
  { name: 'House of Imaginary Walls', level: 5, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You mime an invisible 10-foot-by-10-foot wall adjacent to you and within your reach. The wall is solid to those creatures that don’t disbelieve it, even incorporeal creatures. You and your allies can voluntarily believe the wall exists to continue to treat it as solid, for instance to climb onto it. A creature that disbelieves the illusion is temporarily immune to your house of imaginary walls for 1 minute. The wall doesn’t block creatures that didn’t see your visual performance, nor does it block objects. The wall has AC 10, Hardness equal to double the spell’s rank, and HP equal to quadruple the spell’s rank.', range: 'touch', action: '1' },
  { name: 'Hunter\'s Luck', level: 2, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You have a preternatural ability to remember details about your foes.', action: 'F' },
  { name: 'Hunter\'s Vision', level: 5, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'Your target glows with a magical aura visible only to you and those who follow your lead.', range: '30 feet', target: '1 hunted prey', action: '1' },
  { name: 'Hurtling Stone', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You evoke a magical stone and throw it, with divine guide to your aim.', damage: '2d6', range: '60 feet', target: '1 creature', action: '1', heightened: "(+1) The stone's damage increases by 1d6.", heightenStep: 1, heightenDice: '1d6' },
  { name: 'Hymn of Healing', level: 1, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your glorious singing mends wounds and provides a temporary respite from harm.', range: '30 feet', target: 'you or 1 ally', duration: 'sustained up to 4 rounds', action: '2', heightened: "(+1) The fast healing and temporary Hit Points each increase by 2.", heightenStep: 1 },
  { name: 'Ignite Ambition', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You strengthen a target\'s ambition, increase its resentment of allies, and make its allegiances more susceptible to change.', range: '60 feet', target: 'one creature being influenced', action: 'R' },
  { name: 'Impaling Briars', level: 8, focus: true, tradition: 'Druid', book: 'player-core', desc: 'The ground within the area transforms into a mass of dangerous briars that assault and impede your foes.', damage: '10d6', area: '100-foot emanation', action: '3' },
  { name: 'Interdisciplinary Incantation', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You gather the embers of another caster\'s spell, using your understanding of unified magic to pick apart their formulas and incantations well enough to…', action: 'R' },
  { name: 'Invisibility Cloak', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You become Invisible, with the same restrictions as the 2nd-rank Invisibility spell.', action: '2' },
  { name: 'Know the Enemy', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You quickly remind yourself of useful information.', action: 'R' },
  { name: 'Life Boost', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Life force from your patron floods into the target, ensuring they can continue doing your patron\'s will for just a little longer.', range: '30 feet', target: '1 creature', duration: '4 rounds', action: '1', heightened: "(+1) The fast healing increases by 2.", heightenStep: 1 },
  { name: 'Lingering Composition', level: 1, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You add a flourish to your composition to extend its benefits.', action: 'F' },
  { name: 'Localized Quake', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You shake the earth, toppling nearby creatures.', damage: '4d6', action: '2', heightened: "(+1) Increase the damage by 2d6.", heightenStep: 1, heightenDice: '2d6' },
  { name: 'Loremaster\'s Etude', level: 1, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You call upon your muse\'s deep mysteries, granting the target a greater ability to think and recall information.', range: '30 feet', target: 'you or the triggering ally', action: 'F' },
  { name: 'Lucky Break', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Reroll the saving throw and use the better result.', action: 'R' },
  { name: 'Magic Hide', level: 1, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'Your animal companion grows a thicker hide, matted fur, or a harder shell, granting it a +1 status bonus to AC.', range: '30 feet', target: 'your animal companion', duration: '1 minute', action: '1' },
  { name: 'Magic\'s Vessel', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'A creature becomes a divine receptacle for pure magical energy.', range: 'touch', target: '1 creature', duration: 'sustained up to 1 minute', action: '1' },
  { name: 'Malicious Shadow', level: 3, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron warps the target\'s shadow into a deadly form, such as strangling hands, a dangerous weapon, harrying runes, or the like.', damage: '2d10', range: '30 feet', target: '1 creature', action: '2', heightened: "(+2) The Strike damage increases by 1d10.", heightenStep: 2, heightenDice: '1d10' },
  { name: 'Malignant Sustenance', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You embed a seed of void energy in an undead creature, restoring its unnatural vigor.', range: 'touch', target: '1 willing undead creature', action: '2' },
  { name: 'Moonbeam', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You shine a ray of moonlight.', damage: '2d6', range: '120 feet', target: '1 creature', action: '2', heightened: "(+1) The ray's damage increases by 1d6.", heightenStep: 1, heightenDice: '1d6' },
  { name: 'Mystic Beacon', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'The next damaging or healing spell the target casts before the start of your next turn deals damage or restores Hit Points as if the spell were heightened…', range: '30 feet', target: '1 willing creature', action: '1' },
  { name: 'Nature\'s Bounty', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'A palm-sized raw fruit or vegetable of your choice appears in your open hand.', action: '1' },
  { name: 'Needle of Vengeance', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'A long, jagged needle jabs into the target foe\'s psyche whenever it tries to attack a creature your patron holds in special regard.', range: '30 feet', target: '1 enemy', duration: 'sustained up to 1 minute', action: '1', heightened: "(+1) Increase the damage by 2.", heightenStep: 1 },
  { name: 'Nudge Fate', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'The barest spin of your patron’s spool is enough to alter fate. When the target fails an attack roll, skill check, or saving throw and a +1 status bonus would turn a critical failure into a failure, or failure into a success, you grant the target a +1 status bonus to the check retroactively, changing the outcome appropriately. The spell then ends. If you cast nudge fate while a previous casting of this hex is still in effect, the previous effect ends.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Ode to Ouroboros', level: 5, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your ode staves off death.', range: '60 feet', target: 'the triggering creature', action: 'R' },
  { name: 'Overstuff', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Huge amounts of food and drink fill the target.', range: '30 feet', target: '1 living creature', action: '2' },
  { name: 'Patron\'s Puppet', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'At your unspoken plea, your patron temporarily assumes control over your familiar.', action: 'F' },
  { name: 'Perfected Body', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your body\'s perfection keeps you just a little bit healthier than most.', action: 'R' },
  { name: 'Perfected Mind', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You meditate upon perfection to remove all distractions from your mind.', action: '1' },
  { name: 'Personal Blizzard', level: 3, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron\'s breath becomes blizzard of obscuring, scouring ice that follows your target.', damage: '1d6', range: '30 feet', target: '1 creature', action: '1', heightened: "(+1) The cold damage and persistent cold damage increase by 1 (2 on a critical failure).", heightenStep: 1, heightenDice: '1' },
  { name: 'Phase Familiar', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron momentarily recalls your familiar to the ether, shifting it from its solid, physical form into a ghostly version of itself.', range: '60 feet', target: 'your familiar', action: 'R', heightened: "(+1) Increase the resistance by 2.", heightenStep: 1 },
  { name: 'Pied Piping', level: 10, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your performance enraptures listeners, compelling them to follow you.', action: '2' },
  { name: 'Precious Metals', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your deity blesses base metals to transform them into precious materials.', range: 'touch', target: '1 metal shield or weapon, 1 suit of metal armor, or up to 1 Bulk of metal material (such as coins or metal-tipped ammunition)', action: '1' },
  { name: 'Primal Summons', level: 6, focus: true, tradition: 'Druid', book: 'player-core', desc: 'You enhance a summoned creature with the power of the elements.', action: 'F' },
  { name: 'Protective Wards', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You expand a ring of glyphs that shields your allies.', area: '5-foot emanation', duration: 'sustained up to 1 minute', action: '1' },
  { name: 'Protector\'s Sacrifice', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You protect your ally by suffering in their stead.', range: '30 feet', action: 'R', heightened: "(+1) The damage you redirect increases by 3.", heightenStep: 1 },
  { name: 'Protector\'s Sphere', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'A protective aura emanates out from you, safeguarding you and your allies.', area: '15-foot emanation', action: '2' },
  { name: 'Pulse of Civilization', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You tap into the zeitgeist of any settlements in range.', range: '25 miles', action: '2' },
  { name: 'Pushing Gust', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Giving the air a push, you buffet the target with a powerful gust of wind; it must attempt a Fortitude save.', range: '500 feet', target: '1 creature', action: '2' },
  { name: 'Rallying Anthem', level: 2, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your song moves allies to protect themselves more effectively. You and all allies in the area gain a +1 status bonus to AC and saving throws, as well as resistance equal to half the spell’s rank to physical damage.', area: '60-foot emanation', action: '1' },
  { name: 'Ranger\'s Bramble', level: 3, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You cause plants in the area to entangle your foes, with the effects of Entangling Flora.', range: '100 feet', area: '5-foot burst', action: '2' },
  { name: 'Read Fate', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You attempt to learn more about the target\'s fate in the short term, usually within the next day for most prosaic creatures, or the next hour or less for…', range: '30 feet', target: '1 creature other than you', action: '2' },
  { name: 'Rebuke Death', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You snatch creatures from the jaws of death, restoring them without the straing of a typical close call.', target: '1 living creature per action spent to Cast this Spell', area: '20-foot emanation', action: '1-3' },
  { name: 'Restorative Moment', level: 5, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron weaves the threads of time around the target, giving them some of the benefits of a day\'s passage.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Retributive Pain', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You vengefully reflect your pain upon your tormentor.', range: '30 feet', target: 'the triggering creature', action: 'R' },
  { name: 'Rune of Observation', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You inscribe an invisible eye-shaped rune in the air, creating a sensor as Clairvoyance.', range: '500 feet', action: '1' },
  { name: 'Safeguard Secret', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You ensure a secret remains safe from prying spies.', range: '30 feet', target: 'you and any number of willing allies', action: '2' },
  { name: 'Savor the Sting', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You inflict pain upon the target and revel in their anguish.', damage: '1d4', range: 'touch', target: '1 creature', action: '1', heightened: "(+1) The initial damage increases by 1d4 and the persistent damage increases by 1d4.", heightenStep: 1, heightenDice: '1d4' },
  { name: 'Scholarly Recollection', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Speaking a short prayer as you gather your thoughts, you\'re blessed to find yourself pointed in the right direction.', action: 'R' },
  { name: 'Scramble Body', level: 1, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'Your magic throws the creature\'s biology into disarray, inducing nausea, fever, and other unpleasant conditions.', range: '30 feet', target: '1 living creature', action: '2' },
  { name: 'Shared Nightmare', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Merging minds with the target, you swap distressing visions.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Shifting Form', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'You change your body to better suit the moment.', action: '1' },
  { name: 'Shroud of Night', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron blankets the target’s eyes in darkness. If you cast this hex on a willing ally (for instance, one with light blindness), the ally can choose which result it gets without rolling. Success The target is unaffected. Failure The target is shrouded in murky darkness. It treats bright light as dim light, and unless it has greater darkvision, all creatures are concealed to it.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Song of Marching', level: 3, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You maintain a brisk performance that keeps allies on the move. You and your allies in the area can Hustle for the spell’s duration, in addition to your other exploration activities (your exploration activity is Sustaining this spell). You and your allies then become temporarily immune for 1 day. If you enter an encounter while performing this song, you can use your Performance modifier for the initiative roll. You and your affected allies also receive a +1 status bonus to that initiative roll.', area: '60-foot emanation', action: '1' },
  { name: 'Song of Strength', level: 1, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You bolster your allies’ physical strength with a hearty exhortation. You and your allies gain a +1 status bonus to Athletics checks and to their DCs against Athletics skill actions such as Disarm, Reposition, Shove, and Trip.', area: '60-foot emanation', action: '1' },
  { name: 'Soothing Ballad', level: 7, focus: true, tradition: 'Bard', book: 'player-core', desc: 'You draw upon your muse to soothe your allies.', range: '30 feet', target: 'you and up to 9 allies', action: '2' },
  { name: 'Soothing Mist', level: 2, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You call forth a magical mist that envelops a creature.', damage: '2d8', range: '30 feet', target: '1 willing living creature or 1 undead creature', action: '2', heightened: "(+1) The amount of healing (or damage to an undead target) increases by 1d8, and the persistent vitality damage to an undead creature increases by 1.", heightenStep: 1, heightenDice: '1d8' },
  { name: 'Soothing Words', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You attempt to calm the target by uttering soothing words in a calm and even tone.', range: '30 feet', target: '1 ally', duration: '1 minute', action: '1', heightened: "(5th) The bonus to saves increases to +2, or +3 against emotion effects.", heightenAt: [5] },
  { name: 'Spiral of Horrors', level: 4, focus: true, tradition: 'Wizard', book: 'player-core', desc: 'Shades and spirits howl and whirl around you in a display that strikes fear into the hearts of all who witness it.', area: '30-foot emanation', action: '2' },
  { name: 'Stoke the Heart', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron fills a creature with fervor, empowering their blows. The target gains a +2 status bonus to damage rolls.', range: '30 feet', target: '1 creature', action: '1', heightened: "(+2) The status bonus to damage increases by 1.", heightenStep: 2 },
  { name: 'Storm Lord', level: 9, focus: true, tradition: 'Druid', book: 'player-core', desc: 'The sky above you darkens in a matter of moments, swirling with ominous clouds punctuated by flashes of lighting.', damage: '10d6', area: '100-foot emanation', action: '2' },
  { name: 'Stormwind Flight', level: 4, focus: true, tradition: 'Druid', book: 'player-core', desc: 'Powerful winds carry you smoothly through the air, giving you a fly Speed equal to your Speed.', action: '2' },
  { name: 'Sudden Shift', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You swiftly move from a dangerous spot and veil yourself.', duration: 'until the end of your next turn', action: 'R' },
  { name: 'Sweet Dream', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'With your soothing words, you lull the target into an enchanting dream.', range: '30 feet', target: '1 willing creature', duration: '1 hour', action: '2', heightened: "(4th) The bonus for a dream of insight or glamor is +2. (7th) The bonus for a dream of insight or glamor is +3.", heightenAt: [4, 7] },
  { name: 'Symphony of the Unfettered Heart', level: 5, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your symphony lifts listeners from their worldly concerns.', range: '30 feet', target: 'you or 1 ally', action: '2' },
  { name: 'Take its Course', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'When someone has overindulged, you can hasten them past the worst of their affliction or intensify their misery.', range: 'touch', target: '1 creature', action: '2' },
  { name: 'Tempest Surge', level: 1, focus: true, tradition: 'Druid', book: 'player-core', desc: 'You surround a foe in a swirling storm of violent winds, roiling clouds, and crackling lightning.', damage: '1d12', range: '30 feet', target: '1 creature', action: '2', heightened: "(+1) The initial damage increases by 1d12.", heightenStep: 1, heightenDice: '1d12' },
  { name: 'Tempt Fate', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You twist the forces of fate to make a moment dire or uneventful, with no in-between.', range: '120 feet', target: 'the triggering creature', action: 'R' },
  { name: 'Terrain Transposition', level: 5, focus: true, tradition: 'Ranger', book: 'player-core', desc: 'You mystically transpose your current location with another.', range: '90 feet', action: '2' },
  { name: 'Tidal Surge', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You call forth a tremendous wave to move the target either in a body of water or on the ground.', range: '60 feet', target: '1 creature', action: '1' },
  { name: 'Touch of Obedience', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your imperious touch erodes the target\'s willpower, making it easier to control.', range: 'touch', target: '1 living creature', duration: 'varies', action: '1' },
  { name: 'Touch of the Moon', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'When you touch the target, a symbol of the moon appears on its forehead, glowing with soft moonlight.', range: 'touch', target: '1 creature', action: '1' },
  { name: 'Touch of Undeath', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You attack the target\'s life force with undeath, dealing 1d6 void damage.', damage: '1d6', range: 'touch', target: '1 living creature', duration: 'varies', action: '1', heightened: "(+1) The damage increases by 1d6.", heightenStep: 1, heightenDice: '1d6' },
  { name: 'Traveler\'s Transit', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You add power to your muscles, allowing you to swim or climb walls with ease.', action: '2' },
  { name: 'Trickster\'s Twin', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You rarely settle for being in just one place.', range: '30 feet', target: '1 creature', action: '2' },
  { name: 'Triple Time', level: 2, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your music sets a fast pace. You and all allies in the area gain a +10-foot status bonus to all Speeds for 1 round.', area: '60-foot emanation', action: '1' },
  { name: 'Unimpeded Stride', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Divine grace ensure that nothing can keep you prisoner or hold you back.', action: '1' },
  { name: 'Unity', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You put up a united defense.', range: '30 feet', target: 'each ally targeted by the triggering spell', action: 'R' },
  { name: 'Untamed Form', level: 1, focus: true, tradition: 'Druid', book: 'player-core', desc: 'You reach within for a different part of yourself, and you set it free, transforming your body into another form.', duration: 'varies', action: '2', heightened: "(2nd) You can transform into shapes listed in animal form.", heightenAt: [2] },
  { name: 'Untamed Shift', level: 1, focus: true, tradition: 'Druid', book: 'player-core', desc: 'You transform just a part of your body.', duration: '1 minute', action: '1-2', heightened: "(6th) You can choose up to two effects from the list. Untamed claws leave terrible, ragged wounds that also deal 2d6 persistent bleed damage on a hit, and untamed jaws are envenomed, also dealing 2d6 persistent poison damage on a hit. (10th) You can choose up to three effects from the list. Untamed claws deal 4d6 persistent bleed damage on a hit, and untamed jaws deal 4d6 persistent poison damage on a hit.", heightenAt: [6, 10] },
  { name: 'Uplifting Overture', level: 1, cantrip: true, focus: true, tradition: 'Bard', book: 'player-core', desc: 'Your performance makes allies feel they can succeed at anything. This counts as having prepared to Aid your ally on a skill check of your choice. When you later use the Aid reaction, you can roll Performance instead of the normal skill check, and if you roll a failure, you get a success instead. If you are legendary in Performance, you automatically critically succeed. The GM might rule that you can’t use this ability if the act of encouraging your ally would interfere with the skill check (such as a check to Sneak quietly or maintain a disguise).', range: '60 feet', target: '1 ally', action: '1' },
  { name: 'Veil of Confidence', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You surround yourself in a veil of confidence.', duration: '1 minute', action: '1' },
  { name: 'Veil of Dreams', level: 1, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron draws the target into a drowsy state, causing daydreams and sluggishness.', range: '30 feet', target: '1 creature', duration: 'sustained up to 1 minute', action: '1' },
  { name: 'Vibrant Thorns', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Your body sprouts a coat of brambly thorns that thrive on life magic.', duration: '1 minute', action: '1', heightened: "(+1) The damage increases by 1, or 1d6 after you cast a vitality spell.", heightenStep: 1 },
  { name: 'Waking Nightmare', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You fill the creature\'s mind with a terrifying vision.', range: '30 feet', target: '1 creature', duration: 'varies', action: '2', heightened: "(+1) The mental damage increases by 1.", heightenStep: 1 },
  { name: 'Weapon Surge', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'Holding your weapon aloft, you fill it with divine energy.', range: 'touch', target: '1 weapon you\'re wielding', duration: 'until the start of your next turn', damage: '1d6', action: '1', heightened: "(5th) The attack deals 2d6 additional spirit damage. (9th) The attack deals 3d6 additional spirit damage.", heightenAt: [5, 9] },
  { name: 'Whispering Quiet', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You suppress sound in an area, preventing anyone from giving away valuable secrets.', range: '60 feet', area: '15-foot burst', duration: '1 minute', action: '2' },
  { name: 'Wilding Word', level: 1, cantrip: true, focus: true, tradition: 'Witch', book: 'player-core', desc: 'Your patron’s majesty—or their displeasure—comes in a growl from your throat, making other creatures reluctant to harm you. The target must attempt a Will save; if the creature is an animal, fungus, or plant, it takes a –1 circumstance penalty to its save. Critical Success The target is unaffected. Success When the target attempts an attack roll or skill check that would harm you, it takes a –2 status penalty to its roll. Failure As success, but the target also becomes sickened 1 each time it damages you. Critical Failure As failure, but the sickened value is 2.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Word of Freedom', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You utter a liberating word of power that frees a creature.', range: '30 feet', target: '1 creature', action: '1' },
  { name: 'Word of Truth', level: 1, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You speak a statement you believe to be true and that is free of any attempt to deceive through twisting words, omission, and so on.', duration: 'sustained up to 1 minute', action: '1' },
  { name: 'Zeal for Battle', level: 4, focus: true, tradition: 'Cleric', book: 'player-core', desc: 'You stoke the righteous anger within yourself and an ally.', range: '10 feet', target: 'you and the triggering ally', action: 'R' },
];

